// Package moultest issues `moultest`, a NATIVE coin, and gives it away.
//
// Native here means the chain's own bank holds it, exactly as it holds GNOT.
// It is not a GRC20: there is no ledger in this realm's storage, no balance
// map, no Transfer function, no allowance. A realm with the right banker calls
// IssueCoin once and from that moment the coin is a first-class chain object,
// and this realm has no further say in who holds it.
//
// # What that buys, and what it costs
//
// The interesting half is what disappears. Moving moultest needs no code here
// at all: a plain bank send does it, from any wallet, with no realm call and no
// approval dance, because the transfer is a tm2 bank message rather than a
// function call. It can also RIDE a transaction: the `-send` envelope of a call
// carries it into the realm being called, which is the one thing no GRC20 can
// do, and [Tip] exists to show it. The account page of any explorer lists it
// beside GNOT with nothing registered anywhere.
//
// The half that is worse is the authority. A GRC20's mint and burn live behind
// a PrivateLedger this realm chooses to guard; a native coin's live in a banker
// minted from a realm handle, and banker.RemoveCoin takes an ARBITRARY address.
// Nothing in the chain stops the issuing realm from deleting anybody's balance
// at any time. This realm does not expose that (see [Burn], which is scoped to
// the caller and to nobody else), but "does not expose it" is the only
// protection there is, and it lasts exactly as long as the deployed code. That
// is the real asymmetry against a GRC20, not the ergonomics.
//
// There is no decimals field either, nor a name, nor a symbol: a native denom
// is a string and nothing else. 1000 moultest is a thousand moultest.
//
// # Why it is capped
//
// Free money with no ceiling is a spam vector rather than a faucet, so [Claim]
// is bounded four ways, and the caps are the point of the experiment as much as
// the coin is:
//
//   - [ClaimAmount] per call, to the CALLER only, never to an address the
//     caller names, so nobody can dust a stranger with it.
//   - [ClaimEvery] blocks of cooldown between two claims by one account.
//   - [MaxPerAccount] over that account's lifetime.
//   - [MaxSupply] over the realm's lifetime.
//
// [Burn] does not give any of it back. Issuance is counted monotonically, so
// claim-burn-claim cannot walk around the per-account cap; what burning moves
// is the circulating supply, which is why the two numbers are reported
// separately.
//
// # It is a private realm
//
// gnomod.toml declares private = true, so this path can be redeployed with
// corrected code instead of being abandoned for a v1. The price is measured
// elsewhere in this repo and applies here too: the coins survive a redeploy
// (they are bank state, held at their owners' addresses, and the denom embeds
// the package path, which does not move), and everything on this page does not.
// Claim history, caps consumed and the tip board all return to their init
// values, which would hand every account a fresh [MaxPerAccount]. For a coin
// that is worthless by construction that is an acceptable trade; it would not
// be for one that is not.
package moultest

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// Name is the coin's base denom: the part after the colon. The chain caps
	// it at 16 lowercase characters.
	Name = "moultest"
	// Path is this realm's package path. The denom embeds it verbatim, so the
	// coin and the code are permanently the same name.
	Path = "gno.land/r/moul/x/moultest/v0"
	// Link is Path as a gnoweb route.
	Link = "/r/moul/x/moultest/v0"
)

// Denom is the full chain denom, "/" + [Path] + ":" + [Name]. This is the
// string a wallet, an explorer or a `-send` flag needs; the bank knows nothing
// about the realm behind it.
var Denom = chain.CoinDenom(Path, Name)

const (
	// ClaimAmount is issued per successful [Claim].
	ClaimAmount = int64(10_000)
	// ClaimEvery is the cooldown, in blocks, between two claims by one account.
	ClaimEvery = int64(100)
	// MaxPerAccount is the lifetime ceiling on what one address can claim here,
	// ten claims' worth. Burning does not raise it.
	MaxPerAccount = int64(100_000)
	// MaxSupply is the lifetime ceiling on what this realm can ever issue: a
	// hundred claims' worth, all told. Nothing lowers it, so the coin cannot be
	// inflated after the fact, and the experiment has an end rather than a
	// budget. A faucet meant to serve a crowd would put the ceiling somewhere
	// else; this one is meant to run out.
	MaxSupply = int64(1_000_000)

	// MaxNote is the longest tip note kept, in bytes.
	MaxNote = 120
	// MaxTips is how many tips the board shows. Older ones fall off.
	MaxTips = 20
)

type account struct {
	lastClaim int64 // block height of the most recent claim
	claims    int64 // how many times this address has claimed
	issued    int64 // lifetime total issued to it, never decremented
}

// Tip is one entry of the public board written by [Tip].
type tip struct {
	from   address
	to     address
	amount int64
	note   string
	height int64
}

var (
	accounts = avl.NewTree() // address string -> *account

	// issued and burned are counted here rather than derived from the bank:
	// TotalCoin reports what CIRCULATES, and the caps are about what was ever
	// minted. The two differ by exactly `burned`, which a test pins.
	issued int64
	burned int64

	tips []*tip // most recent last, at most MaxTips
)

// Claim issues [ClaimAmount] of moultest to the caller and returns it.
//
// It never issues to an address the caller names. That is deliberate: a faucet
// that mints to a third party is a way to spray a denom nobody asked for into
// strangers' wallets, and their account page then carries it forever.
func Claim(cur realm) int64 {
	who := caller(cur)
	a := accountOf(who)
	now := runtime.ChainHeight()

	if a.claims > 0 && now < a.lastClaim+ClaimEvery {
		panic(ufmt.Sprintf("too soon: next claim at block %d, current %d",
			a.lastClaim+ClaimEvery, now))
	}
	if a.issued+ClaimAmount > MaxPerAccount {
		panic(ufmt.Sprintf("account cap reached: %d of %d already claimed by this address",
			a.issued, MaxPerAccount))
	}
	if issued+ClaimAmount > MaxSupply {
		panic(ufmt.Sprintf("supply cap reached: %d of %d already issued",
			issued, MaxSupply))
	}

	a.lastClaim = now
	a.claims++
	a.issued += ClaimAmount
	accounts.Set(who.String(), a)
	issued += ClaimAmount

	banker.NewBanker(banker.BankerTypeRealmIssue, cur).IssueCoin(who, Denom, ClaimAmount)
	return ClaimAmount
}

// Burn destroys `amount` of the CALLER's moultest, and only the caller's.
//
// The banker this realm holds could remove coins from any address on the chain
// without asking, so the `who` here is read from the call frame and is never a
// parameter. A clawback is what an issuing realm is always able to write; the
// choice not to is made here, once, and cannot be revisited without a redeploy.
//
// Burning lowers what circulates and does not return any cap headroom: see
// [MaxPerAccount].
func Burn(cur realm, amount int64) {
	if amount <= 0 {
		panic("burn a positive amount")
	}
	who := caller(cur)
	if bal := BalanceOf(who); bal < amount {
		panic(ufmt.Sprintf("balance is %d, cannot burn %d", bal, amount))
	}

	banker.NewBanker(banker.BankerTypeRealmIssue, cur).RemoveCoin(who, Denom, amount)
	burned += amount
}

// Tip forwards the moultest attached to THIS transaction to `to`, and writes
// the note on a public board.
//
// The coin arrives in the `-send` envelope of the call, credited to this
// realm's address before a line of this function runs, and leaves through a
// BankerTypeOriginSend banker, whose whole authority is that envelope: it can
// spend what this message paid in and not one coin more, not even out of the
// realm's own balance. So the realm can route a payment it was handed while
// being structurally unable to touch anything else.
//
// A GRC20 has no equivalent. Its tokens cannot ride a message, so the same flow
// costs an Approve, then a call, then an allowance that outlives both.
//
// Anything else in the envelope (the GNOT covering a storage deposit, say) is
// left alone and stays with the realm.
func Tip(cur realm, to address, note string) int64 {
	who := caller(cur)
	if !to.IsValid() {
		panic("tip a valid address")
	}
	if to == who {
		panic("tip somebody else")
	}
	if len(note) > MaxNote {
		panic(ufmt.Sprintf("note is %d bytes, max %d", len(note), MaxNote))
	}

	amount := unsafe.OriginSend().AmountOf(Denom)
	if amount <= 0 {
		panic("attach moultest to the transaction: -send " + Denom)
	}

	b := banker.NewBanker(banker.BankerTypeOriginSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))

	tips = append(tips, &tip{
		from:   who,
		to:     to,
		amount: amount,
		note:   note,
		height: runtime.ChainHeight(),
	})
	if len(tips) > MaxTips {
		tips = tips[len(tips)-MaxTips:]
	}
	return amount
}

// BalanceOf returns what the bank holds of moultest for `who`. It reads the
// chain, not this realm: a balance this realm never saw counts the same.
func BalanceOf(who address) int64 {
	return banker.NewReadonlyBanker().GetCoin(who, Denom)
}

// Circulating returns how much moultest exists right now, from the bank.
func Circulating() int64 {
	return banker.NewReadonlyBanker().TotalCoin(Denom)
}

// Issued returns how much this realm has ever issued. It only grows, and it is
// what [MaxSupply] caps.
func Issued() int64 { return issued }

// Burned returns how much has been destroyed through [Burn].
func Burned() int64 { return burned }

// NextClaim returns the block height at which `who` may claim again, and
// whether they have ever claimed at all.
func NextClaim(who address) (int64, bool) {
	a := accounts.Get(who.String())
	if a == nil {
		return 0, false
	}
	return a.(*account).lastClaim + ClaimEvery, true
}

// ClaimedBy returns the lifetime total issued to `who` by this realm, which is
// what [MaxPerAccount] caps.
func ClaimedBy(who address) int64 {
	a := accounts.Get(who.String())
	if a == nil {
		return 0
	}
	return a.(*account).issued
}

// Accounts returns how many addresses have ever claimed.
func Accounts() int { return accounts.Size() }

func accountOf(who address) *account {
	if v := accounts.Get(who.String()); v != nil {
		return v.(*account)
	}
	return &account{}
}

// caller is the account or realm that crossed into this one.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("moultest: stale realm token")
	}
	return cur.Previous().Address()
}

package moultest

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// testing.SetRealm governs only the crossing calls made from the frame that
// called it, so every account switch below is written inline in the test body
// rather than in a helper.

func TestDenom(t *testing.T) {
	// The denom is what a wallet, an explorer and a -send flag all type, and it
	// is immutable once the first coin exists. Pin the literal: deriving it from
	// Path would restate the code rather than check it.
	uassert.Equal(t, "/gno.land/r/moul/x/moultest/v0:moultest", Denom)
}

func TestClaimIssuesRealCoins(cur realm, t *testing.T) {
	alice := testutils.TestAddress("mt-alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	_, ever := NextClaim(alice)
	uassert.False(t, ever, "no claim recorded before the first one")
	uassert.Equal(t, int64(0), BalanceOf(alice))

	before := Circulating()
	got := Claim(cross(cur))

	uassert.Equal(t, ClaimAmount, got)
	// The balance comes from the bank, not from realm storage: nothing in this
	// realm records who holds what.
	uassert.Equal(t, ClaimAmount, BalanceOf(alice))
	uassert.Equal(t, before+ClaimAmount, Circulating())
	uassert.Equal(t, ClaimAmount, ClaimedBy(alice))

	next, ever := NextClaim(alice)
	uassert.True(t, ever, "a cooldown is recorded")
	uassert.Equal(t, ClaimEvery, next-123, "first test block is 123, so the cooldown lands there")
}

func TestClaimCooldown(cur realm, t *testing.T) {
	bob := testutils.TestAddress("mt-bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	Claim(cross(cur))
	uassert.AbortsContains(t, cur, "too soon", func() { Claim(cross(cur)) })

	testing.SkipHeights(ClaimEvery - 1)
	uassert.AbortsContains(t, cur, "too soon", func() { Claim(cross(cur)) })

	testing.SkipHeights(1)
	Claim(cross(cur))
	uassert.Equal(t, 2*ClaimAmount, BalanceOf(bob))
}

func TestAccountCap(cur realm, t *testing.T) {
	carol := testutils.TestAddress("mt-carol")
	testing.SetRealm(testing.NewUserRealm(carol))

	for ClaimedBy(carol)+ClaimAmount <= MaxPerAccount {
		Claim(cross(cur))
		testing.SkipHeights(ClaimEvery)
	}
	uassert.Equal(t, MaxPerAccount, ClaimedBy(carol))
	uassert.AbortsContains(t, cur, "account cap reached", func() { Claim(cross(cur)) })

	// Waiting does not help: the cooldown is not what stopped it.
	testing.SkipHeights(ClaimEvery * 10)
	uassert.AbortsContains(t, cur, "account cap reached", func() { Claim(cross(cur)) })
}

func TestBurnIsScopedToTheCaller(cur realm, t *testing.T) {
	dave := testutils.TestAddress("mt-dave")
	erin := testutils.TestAddress("mt-erin")

	testing.SetRealm(testing.NewUserRealm(erin))
	Claim(cross(cur))
	erinBefore := BalanceOf(erin)

	testing.SetRealm(testing.NewUserRealm(dave))
	Claim(cross(cur))

	issuedBefore, burnedBefore, circBefore := Issued(), Burned(), Circulating()
	claimedBefore := ClaimedBy(dave)

	Burn(cross(cur), 400)

	uassert.Equal(t, ClaimAmount-400, BalanceOf(dave))
	uassert.Equal(t, circBefore-400, Circulating(), "burning destroys the coin, it is not moved")
	uassert.Equal(t, burnedBefore+400, Burned())
	// Issuance is monotonic on purpose: if burning gave cap headroom back,
	// claim-burn-claim would be an unlimited faucet.
	uassert.Equal(t, issuedBefore, Issued())
	uassert.Equal(t, claimedBefore, ClaimedBy(dave))
	// Burn takes no address, so erin cannot be reached from dave's call.
	uassert.Equal(t, erinBefore, BalanceOf(erin))

	uassert.AbortsContains(t, cur, "cannot burn", func() { Burn(cross(cur), 1_000_000) })
	uassert.AbortsContains(t, cur, "positive amount", func() { Burn(cross(cur), 0) })
	uassert.AbortsContains(t, cur, "positive amount", func() { Burn(cross(cur), -5) })
}

func TestTipRidesTheEnvelope(cur realm, t *testing.T) {
	frank := testutils.TestAddress("mt-frank")
	grace := testutils.TestAddress("mt-grace")

	// On chain the -send envelope is credited to this realm's address before
	// the function runs. The test harness has no bank-send primitive, so the
	// credit is issued directly here; SetOriginSend is what the banker checks
	// against, and it is the half that bounds what Tip may spend.
	realmAddr := chain.PackageAddress(Path)
	envelope := chain.NewCoins(chain.NewCoin(Denom, 250))
	testing.IssueCoins(realmAddr, envelope)
	// Unrelated coins already sitting at the realm's address. A RealmSend
	// banker could spend these; the OriginSend one may not, and that is the
	// property being pinned.
	testing.IssueCoins(realmAddr, chain.NewCoins(chain.NewCoin(Denom, 5_000)))
	realmBefore := BalanceOf(realmAddr)

	testing.SetRealm(testing.NewUserRealm(frank))
	testing.SetOriginSend(envelope)
	sent := Tip(cross(cur), grace, "nice work")

	uassert.Equal(t, int64(250), sent)
	uassert.Equal(t, int64(250), BalanceOf(grace), "the tip landed on the recipient")
	uassert.Equal(t, realmBefore-250, BalanceOf(realmAddr),
		"exactly the envelope left the realm, and nothing else it was holding")
	uassert.Equal(t, 1, len(tips))
	uassert.Equal(t, "nice work", tips[0].note)

	testing.SetOriginSend(nil)
}

func TestTipRefusals(cur realm, t *testing.T) {
	heidi := testutils.TestAddress("mt-heidi")
	ivan := testutils.TestAddress("mt-ivan")

	testing.SetRealm(testing.NewUserRealm(heidi))
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "attach moultest", func() { Tip(cross(cur), ivan, "hi") })

	envelope := chain.NewCoins(chain.NewCoin(Denom, 10))
	testing.IssueCoins(chain.PackageAddress(Path), envelope)
	testing.SetOriginSend(envelope)
	uassert.AbortsContains(t, cur, "tip somebody else", func() { Tip(cross(cur), heidi, "me") })
	uassert.AbortsContains(t, cur, "valid address", func() { Tip(cross(cur), "nope", "hi") })
	uassert.AbortsContains(t, cur, "note is", func() {
		Tip(cross(cur), ivan, strings.Repeat("x", MaxNote+1))
	})

	testing.SetOriginSend(nil)
}

func TestSupplyCap(cur realm, t *testing.T) {
	// Fill the remaining supply with fresh accounts, each capped at
	// MaxPerAccount, then check that the next one is refused. Issuance carries
	// across tests, so the loop starts from whatever is left rather than from
	// MaxSupply.
	names := []string{"cap-a", "cap-b", "cap-c", "cap-d", "cap-e", "cap-f",
		"cap-g", "cap-h", "cap-i", "cap-j", "cap-k", "cap-l"}
	for _, name := range names {
		if Issued()+ClaimAmount > MaxSupply {
			break
		}
		who := testutils.TestAddress(name)
		testing.SetRealm(testing.NewUserRealm(who))
		for ClaimedBy(who)+ClaimAmount <= MaxPerAccount && Issued()+ClaimAmount <= MaxSupply {
			Claim(cross(cur))
			testing.SkipHeights(ClaimEvery)
		}
	}
	uassert.Equal(t, MaxSupply, Issued(), "the accounts above exhaust the supply exactly")

	late := testutils.TestAddress("cap-late")
	testing.SetRealm(testing.NewUserRealm(late))
	uassert.AbortsContains(t, cur, "supply cap reached", func() { Claim(cross(cur)) })

	// Burning does not reopen the faucet either: circulating drops, issued does
	// not, and the cap is on issued.
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("cap-a")))
	Burn(cross(cur), 500)
	uassert.Equal(t, MaxSupply, Issued())
	testing.SetRealm(testing.NewUserRealm(late))
	uassert.AbortsContains(t, cur, "supply cap reached", func() { Claim(cross(cur)) })
}

func TestRender(t *testing.T) {
	index := Render("")
	uassert.True(t, strings.Contains(index, "# moultest"), "heading:\n"+index)
	uassert.True(t, strings.Contains(index, Denom), "the denom is on the page")
	uassert.True(t, strings.Contains(index, "| issued, ever |"), "supply table:\n"+index)
	uassert.True(t, strings.Contains(index, "nice work"), "the tip board is shown:\n"+index)

	frank := testutils.TestAddress("mt-frank")
	acct := Render(frank.String())
	uassert.True(t, strings.Contains(acct, frank.String()), "the account section names it:\n"+acct)
	uassert.True(t, strings.Contains(acct, "claimed for life"), acct)

	// A path that is not an address renders the index without an account block.
	uassert.False(t, strings.Contains(Render("not-an-address"), "claimed for life"),
		"a junk path adds no account section")
}

package gno4

import "strings"

// Encode returns the whole game as one string: the 1-based column of each
// move, in order. An empty game is the empty string, a full game is 42 bytes.
//
// The position is not stored, because it is not information: replaying the
// moves reproduces it exactly, including the winner and the winning line. That
// is what lets a match be a URL, a chain event and a test fixture without three
// encoders that can disagree.
func (b *Board) Encode() string {
	var sb strings.Builder
	for _, col := range b.moves {
		sb.WriteByte(byte('1' + col))
	}
	return sb.String()
}

// Decode replays an encoding produced by [Board.Encode].
//
// It replays through [Board.Drop] rather than writing cells directly, so an
// encoding that describes an impossible game (a column overflowing, a move
// after the win) is rejected here instead of becoming a board no rule allows.
// Nothing else in this package can construct an illegal position.
func Decode(s string) (*Board, error) {
	b := New()
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '1' || c > '7' {
			return nil, ErrBadEncoding
		}
		if _, err := b.Drop(int(c - '1')); err != nil {
			return nil, ErrBadEncoding
		}
	}
	return b, nil
}

// String renders the board as seven columns of ASCII, top row first, the way a
// player looks at it. Empty is '.', Red is 'R', Yellow is 'Y'.
//
// This is the debugging view and the one tests assert against. What gnoweb
// shows is [Board.Image]; what a terminal or a diff shows is this.
func (b *Board) String() string {
	var sb strings.Builder
	for row := Rows - 1; row >= 0; row-- {
		for col := 0; col < Cols; col++ {
			switch b.At(col, row) {
			case Red:
				sb.WriteByte('R')
			case Yellow:
				sb.WriteByte('Y')
			default:
				sb.WriteByte('.')
			}
		}
		sb.WriteByte('\n')
	}
	sb.WriteString("1234567\n")
	return sb.String()
}

// Package gno4 is a Connect Four engine: the rules, and nothing else.
//
// It imports no chain package, takes no address and reads no height, so it is
// unit-testable with no node and a realm that uses it stays thin. Everything a
// caller needs to know about a position is derivable from a [Board], and a
// whole game round-trips through a string of at most 42 digits ([Board.Encode]).
//
// Live demo: [r/moul/gno4](/r/moul/gno4).
package gno4

import "errors"

// Cols and Rows are the standard board. They are constants rather than fields
// because every rule below, the win scan in particular, is written against
// them; a variable board is a different package, not a flag on this one.
const (
	Cols = 7
	Rows = 6
)

// Disc identifies whose disc occupies a cell. Empty is the zero value, so a
// freshly allocated Board is a legal empty board with no constructor call.
type Disc byte

const (
	Empty  Disc = 0
	Red    Disc = 1
	Yellow Disc = 2
)

// Other returns the opponent of d, and Empty for Empty.
func (d Disc) Other() Disc {
	switch d {
	case Red:
		return Yellow
	case Yellow:
		return Red
	}
	return Empty
}

func (d Disc) String() string {
	switch d {
	case Red:
		return "red"
	case Yellow:
		return "yellow"
	}
	return "empty"
}

var (
	ErrColumnRange = errors.New("gno4: column out of range")
	ErrColumnFull  = errors.New("gno4: column is full")
	ErrGameOver    = errors.New("gno4: game is over")
	ErrBadEncoding = errors.New("gno4: not a valid game encoding")
)

// Board is a position plus the moves that produced it.
//
// The winner and the winning line are computed once, by the Drop that creates
// them, and stored. A realm renders a finished game far more often than it
// plays a move, and rescanning 69 lines on every Render is gas spent to learn
// something the board already knew.
type Board struct {
	cells  [Cols * Rows]Disc
	moves  []int
	winner Disc
	line   []int
}

// New returns an empty board. Red moves first.
func New() *Board { return &Board{} }

func idx(col, row int) int { return row*Cols + col }

// At returns the disc at (col, row), counting rows from the bottom. Out of
// range is Empty rather than a panic: At is called from render loops that walk
// past the edge on purpose, and a Render that panics is a permanently
// unreadable page.
func (b *Board) At(col, row int) Disc {
	if col < 0 || col >= Cols || row < 0 || row >= Rows {
		return Empty
	}
	return b.cells[idx(col, row)]
}

// Turn returns whose move it is. Red on even move counts, Yellow on odd.
func (b *Board) Turn() Disc {
	if len(b.moves)%2 == 0 {
		return Red
	}
	return Yellow
}

// MoveCount returns how many discs are on the board.
func (b *Board) MoveCount() int { return len(b.moves) }

// Moves returns a copy of the move list, as zero-based column indexes.
func (b *Board) Moves() []int {
	out := make([]int, len(b.moves))
	copy(out, b.moves)
	return out
}

// Height returns how many discs are stacked in col.
func (b *Board) Height(col int) int {
	if col < 0 || col >= Cols {
		return 0
	}
	n := 0
	for row := 0; row < Rows; row++ {
		if b.cells[idx(col, row)] == Empty {
			break
		}
		n++
	}
	return n
}

// Winner returns the disc that made four in a row, or Empty.
func (b *Board) Winner() Disc { return b.winner }

// Line returns the four cell indexes that won, or nil. An index is
// row*Cols+col, the same order [Board.At] uses.
func (b *Board) Line() []int {
	out := make([]int, len(b.line))
	copy(out, b.line)
	return out
}

// Full reports whether all 42 cells are taken.
func (b *Board) Full() bool { return len(b.moves) == Cols*Rows }

// Over reports whether the game is decided: someone won, or the board filled.
func (b *Board) Over() bool { return b.winner != Empty || b.Full() }

// Draw reports whether the board filled with no winner.
func (b *Board) Draw() bool { return b.winner == Empty && b.Full() }

// CanDrop reports whether the current player may play col right now.
func (b *Board) CanDrop(col int) bool {
	return !b.Over() && col >= 0 && col < Cols && b.Height(col) < Rows
}

// Legal returns every column the current player may play. Empty once the game
// is over, which is what makes it safe to render as the move menu.
func (b *Board) Legal() []int {
	out := []int{}
	if b.Over() {
		return out
	}
	for col := 0; col < Cols; col++ {
		if b.Height(col) < Rows {
			out = append(out, col)
		}
	}
	return out
}

// Drop plays the current player's disc into col and returns the row it landed
// on. It is the only method that mutates a Board, so every illegal state this
// package could reach is refused in one place.
func (b *Board) Drop(col int) (int, error) {
	if b.Over() {
		return 0, ErrGameOver
	}
	if col < 0 || col >= Cols {
		return 0, ErrColumnRange
	}
	row := b.Height(col)
	if row >= Rows {
		return 0, ErrColumnFull
	}
	d := b.Turn()
	b.cells[idx(col, row)] = d
	b.moves = append(b.moves, col)
	if line := b.scan(col, row, d); line != nil {
		b.winner = d
		b.line = line
	}
	return row, nil
}

// Clone returns an independent copy. Callers that search (a hint, a bot) mutate
// a clone; a Board handed out by a realm is never a scratch pad.
func (b *Board) Clone() *Board {
	c := &Board{cells: b.cells, winner: b.winner}
	c.moves = make([]int, len(b.moves))
	copy(c.moves, b.moves)
	c.line = make([]int, len(b.line))
	copy(c.line, b.line)
	return c
}

// WinningMove returns a column where d wins on the spot, or -1.
//
// It is deliberately one ply deep. That covers the two things a player wants
// from a board they are looking at ("can I win now", "can they win now, so I
// must block") and costs seven clones; a real search belongs off-chain, in the
// front-end, where nobody pays gas to think.
func (b *Board) WinningMove(d Disc) int {
	if b.Over() {
		return -1
	}
	for col := 0; col < Cols; col++ {
		row := b.Height(col)
		if row >= Rows {
			continue
		}
		if b.scan(col, row, d) != nil {
			return col
		}
	}
	return -1
}

// dirs are the four axes a line can run along: east, north, north-east,
// north-west. Their opposites are covered by scanning both ways from the
// placed disc.
var dirs = [4][2]int{{1, 0}, {0, 1}, {1, 1}, {1, -1}}

// scan looks for a line of four through (col, row) for d.
//
// It never reads (col, row) itself, only the cells around it, so the same scan
// answers both questions this package asks: "did the disc I just placed win"
// and "would a disc placed here win". That is why [Board.WinningMove] needs no
// clone and writes nothing.
func (b *Board) scan(col, row int, d Disc) []int {
	for _, dir := range dirs {
		cells := []int{idx(col, row)}
		for _, sign := range [2]int{1, -1} {
			for step := 1; step < 4; step++ {
				c := col + dir[0]*sign*step
				r := row + dir[1]*sign*step
				if c < 0 || c >= Cols || r < 0 || r >= Rows {
					break
				}
				if b.cells[idx(c, r)] != d {
					break
				}
				cells = append(cells, idx(c, r))
			}
		}
		if len(cells) >= 4 {
			return trimLine(cells, dir, col, row)
		}
	}
	return nil
}

// trimLine reduces a run of five or six to the four cells adjacent to the disc
// that was just played, walking outward from it so the highlighted line always
// contains the winning move.
func trimLine(cells []int, dir [2]int, col, row int) []int {
	out := []int{idx(col, row)}
	for _, sign := range [2]int{1, -1} {
		for step := 1; step < 4 && len(out) < 4; step++ {
			c := col + dir[0]*sign*step
			r := row + dir[1]*sign*step
			if !contains(cells, idx(c, r)) {
				break
			}
			out = append(out, idx(c, r))
		}
	}
	sortInts(out)
	return out
}

func contains(haystack []int, needle int) bool {
	for _, v := range haystack {
		if v == needle {
			return true
		}
	}
	return false
}

// sortInts is an insertion sort. gno has no sort.Slice, and the input is four
// elements, so reaching for anything larger would be theatre.
func sortInts(a []int) {
	for i := 1; i < len(a); i++ {
		v := a[i]
		j := i - 1
		for j >= 0 && a[j] > v {
			a[j+1] = a[j]
			j--
		}
		a[j+1] = v
	}
}

package gno4

import (
	"strings"

	"gno.land/p/nt/svg/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Board geometry, in SVG user units. Everything else is derived, so changing
// cell changes the whole drawing and nothing goes out of step.
const (
	pad  = 10
	cell = 74
	hole = 30

	svgW = Cols*cell + 2*pad
	svgH = Rows*cell + 2*pad
	labY = svgH + 22
)

// The palette. Fixed hex rather than CSS variables: gnoweb renders the SVG
// inside a data URI, which is its own document and inherits nothing from the
// page, so a theme-aware colour would resolve to nothing at all.
const (
	colBoard  = "#1d4ed8"
	colHole   = "#f8fafc"
	colRed    = "#ef4444"
	colYellow = "#facc15"
	colLabel  = "#64748b"
	colWin    = "#0f172a"
)

// SVG returns the board as standalone <svg> markup.
//
// It is a drawing of a position, not a control: there is no script, no link
// and no interactivity, because gnoweb serves this through a data URI and
// would not run any of it. The clickable column menu is the realm's job, as
// ordinary markdown links next to the image.
func (b *Board) SVG() string { return b.canvas().String() }

// Image returns the board as a markdown image, ready to drop into a realm's
// Render output. The SVG travels inline as a data URI, which gnoweb allows for
// image/svg+xml specifically, so the board needs no hosting and no asset
// pipeline: there is nothing to go missing later, and no storage is spent on
// it because it is drawn at render time rather than stored.
func (b *Board) Image(alt string) string { return b.canvas().Render(alt) }

func (b *Board) canvas() *svg.Canvas {
	c := svg.NewCanvas(svgW, svgH+30).WithViewBox(0, 0, svgW, svgH+30)
	c.AddStyle(".win", "stroke:"+colWin+";stroke-width:5")
	c.AddStyle(".last", "stroke:#ffffff;stroke-width:4")
	c.AddStyle(".lab", "font:600 22px system-ui,sans-serif;text-anchor:middle")

	c.Append(svg.NewRectangle(0, 0, svgW, svgH, colBoard))

	last := -1
	if n := len(b.moves); n > 0 {
		lastCol := b.moves[n-1]
		last = idx(lastCol, b.Height(lastCol)-1)
	}
	win := b.line

	for row := Rows - 1; row >= 0; row-- {
		for col := 0; col < Cols; col++ {
			cx := pad + col*cell + cell/2
			cy := pad + (Rows-1-row)*cell + cell/2
			fill := colHole
			switch b.At(col, row) {
			case Red:
				fill = colRed
			case Yellow:
				fill = colYellow
			}
			disc := svg.NewCircle(cx, cy, hole, fill)
			switch {
			case contains(win, idx(col, row)):
				disc.WithClass("win")
			case idx(col, row) == last:
				disc.WithClass("last")
			}
			c.Append(disc)
		}
	}

	for col := 0; col < Cols; col++ {
		x := pad + col*cell + cell/2
		c.Append(svg.NewText(x, labY, ufmt.Sprintf("%d", col+1), colLabel).WithClass("lab"))
	}

	return c
}

// Emoji returns the board as seven columns of coloured squares, top row first.
//
// The text fallback, for the places an image cannot go: a chain event, a
// terminal, a commit message, a diff. It is also what makes the whole package
// legible in a test failure.
func (b *Board) Emoji() string {
	var sb strings.Builder
	for row := Rows - 1; row >= 0; row-- {
		for col := 0; col < Cols; col++ {
			switch b.At(col, row) {
			case Red:
				sb.WriteString("🔴")
			case Yellow:
				sb.WriteString("🟡")
			default:
				sb.WriteString("⚫")
			}
		}
		sb.WriteByte('\n')
	}
	return sb.String()
}

// Package gno4 is Connect Four with the chain as the referee.
//
// The rules live in [p/moul/gno4](/p/moul/gno4/v0), which knows nothing about
// the chain. This realm owns the three things a pure engine cannot: who may
// move, when, and what the world gets to see. That split is the whole design,
// and it is why the engine has 14 tests that need no node.
//
// Nothing here is a wager. A game holds no coins, so there is no escrow, no
// payout and no abandoned-table timeout to get wrong. Money is a second design
// and not a flag on this one.
package gno4

import (
	"chain/runtime"
	"errors"

	"gno.land/p/moul/gno4/v0"
	"gno.land/p/nt/avl/v0"
)

// Game is one table.
//
// The position is NOT stored: Moves is, and the board is replayed from it on
// demand. Three reasons, in the order they matter. The move list is the whole
// game in at most 42 bytes, so storage is minimal and bounded. It is the
// engine's own canonical form, so no second encoder can disagree with it. And
// an engine change never needs a state migration, because the only thing on
// chain is the input, which no engine version can reinterpret.
type Game struct {
	ID      int
	Red     address
	Yellow  address // zero while the table is open
	Moves   string  // gno4.Board.Encode()
	Opened  int64   // block height
	Touched int64   // block height of the last move
	Quit    address // whoever resigned, zero otherwise
}

// Record is a player's standing. Rating is deliberately absent: an Elo needs a
// K factor, a provisional period and an answer for resignations, and every one
// of those is a policy argument that would outlive the three lines of code.
type Record struct {
	Wins, Losses, Draws int
}

var (
	games   avl.Tree // padded id -> *Game
	records avl.Tree // address -> *Record
	nextID  = 1

	// open and live are id lists kept in most-recent-first order. An avl walk
	// could derive both, but it would walk every game ever played to render a
	// page that shows ten, and that cost grows forever.
	open []int
	live []int
	done []int
)

const doneKept = 20 // how many finished games the home page remembers

var (
	ErrNoSuchGame  = errors.New("gno4: no such game")
	ErrNotOpen     = errors.New("gno4: that table is not open")
	ErrOwnGame     = errors.New("gno4: you cannot play yourself")
	ErrNotYours    = errors.New("gno4: you are not in this game")
	ErrNotYourTurn = errors.New("gno4: not your turn")
	ErrFinished    = errors.New("gno4: that game is over")
)

// Open starts a table anyone may join. The caller takes red and moves first.
func Open(cur realm) int {
	caller := cur.Previous().Address()
	g := &Game{
		ID:     nextID,
		Red:    caller,
		Opened: runtime.ChainHeight(),
	}
	nextID++
	games.Set(key(g.ID), g)
	open = prepend(open, g.ID)
	return g.ID
}

// Join takes the yellow seat of an open table.
func Join(cur realm, id int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Yellow != "" {
		panic(ErrNotOpen)
	}
	if g.Red == caller {
		panic(ErrOwnGame)
	}
	g.Yellow = caller
	g.Touched = runtime.ChainHeight()
	open = remove(open, id)
	live = prepend(live, id)
}

// Play drops the caller's disc into col, counted from 1.
//
// Every refusal below is a rule the engine cannot enforce, because the engine
// has no idea who is calling. The engine still owns "is that column legal",
// and Drop is what answers it.
func Play(cur realm, id, col int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Over() {
		panic(ErrFinished)
	}
	if g.Yellow == "" {
		panic(ErrNotOpen)
	}
	b := g.Board()
	var seat address
	if b.Turn() == gno4.Red {
		seat = g.Red
	} else {
		seat = g.Yellow
	}
	if caller != g.Red && caller != g.Yellow {
		panic(ErrNotYours)
	}
	if caller != seat {
		panic(ErrNotYourTurn)
	}
	if _, err := b.Drop(col - 1); err != nil {
		panic(err)
	}
	g.Moves = b.Encode()
	g.Touched = runtime.ChainHeight()
	if b.Over() {
		finish(g, b.Winner())
	}
}

// Resign concedes. A game nobody resigns and nobody finishes stays live
// forever; that is a known hole, and a timeout is the fix, not a cron.
func Resign(cur realm, id int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Over() {
		panic(ErrFinished)
	}
	if caller != g.Red && caller != g.Yellow {
		panic(ErrNotYours)
	}
	g.Quit = caller
	g.Touched = runtime.ChainHeight()
	if g.Yellow == "" {
		// An open table nobody joined: withdraw it, and score nothing.
		open = remove(open, id)
		done = trim(prepend(done, id))
		return
	}
	winner := gno4.Red
	if caller == g.Red {
		winner = gno4.Yellow
	}
	finish(g, winner)
}

func finish(g *Game, winner gno4.Disc) {
	live = remove(live, g.ID)
	done = trim(prepend(done, g.ID))
	switch winner {
	case gno4.Red:
		record(g.Red).Wins++
		record(g.Yellow).Losses++
	case gno4.Yellow:
		record(g.Yellow).Wins++
		record(g.Red).Losses++
	default:
		record(g.Red).Draws++
		record(g.Yellow).Draws++
	}
}

// Board replays the move list. It never returns nil and never panics: a stored
// encoding that no longer decodes would make the game's page unreadable
// forever, so it degrades to an empty board instead.
func (g *Game) Board() *gno4.Board {
	b, err := gno4.Decode(g.Moves)
	if err != nil {
		return gno4.New()
	}
	return b
}

// Over reports whether the game is settled, by the rules or by a resignation.
func (g *Game) Over() bool { return g.Quit != "" || g.Board().Over() }

// Winner returns the winning seat, or the zero address on a draw, an open
// table or a game still in play.
func (g *Game) Winner() address {
	if g.Quit != "" {
		if g.Quit == g.Red {
			return g.Yellow
		}
		return g.Red
	}
	switch g.Board().Winner() {
	case gno4.Red:
		return g.Red
	case gno4.Yellow:
		return g.Yellow
	}
	return ""
}

// GameOf returns a copy of one game's public facts, for another realm or an
// off-chain reader that wants state rather than a rendered page.
//
// It returns values, not the *Game: this realm is private = true, so handing
// out a pointer into its own storage is the one thing that cannot be undone
// later.
func GameOf(id int) (red, yellow address, moves string, over bool) {
	v := games.Get(key(id))
	if v == nil {
		return "", "", "", false
	}
	g := v.(*Game)
	return g.Red, g.Yellow, g.Moves, g.Over()
}

// RecordOf returns a player's standing.
func RecordOf(addr address) (wins, losses, draws int) {
	v := records.Get(addr.String())
	if v == nil {
		return 0, 0, 0
	}
	r := v.(*Record)
	return r.Wins, r.Losses, r.Draws
}

func mustGame(id int) *Game {
	v := games.Get(key(id))
	if v == nil {
		panic(ErrNoSuchGame)
	}
	return v.(*Game)
}

func record(addr address) *Record {
	if v := records.Get(addr.String()); v != nil {
		return v.(*Record)
	}
	r := &Record{}
	records.Set(addr.String(), r)
	return r
}

// key zero-pads an id so avl's byte ordering is numeric ordering. ufmt has no
// width verb, which is why this is five lines instead of one.
func key(id int) string {
	s := itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	out := ""
	for n > 0 {
		out = string(rune('0'+n%10)) + out
		n /= 10
	}
	if neg {
		out = "-" + out
	}
	return out
}

func prepend(list []int, id int) []int {
	return append([]int{id}, list...)
}

func remove(list []int, id int) []int {
	out := make([]int, 0, len(list))
	for _, v := range list {
		if v != id {
			out = append(out, v)
		}
	}
	return out
}

func trim(list []int) []int {
	if len(list) > doneKept {
		return list[:doneKept]
	}
	return list
}

// Feed returns every game this realm knows, one per line, newest first:
//
//	<id>\t<red>\t<yellow>\t<moves>\t<state>
//
// where state is open, live, or the address that won, or "draw".
//
// A realm that only renders markdown forces its own front-end to scrape the
// page it renders, and then a wording change breaks the app. So there are two
// views of the same state: Render for people, Feed for programs. Neither is
// derived from the other, both are derived from the state, and the machine one
// is the cheap one to keep stable.
func Feed() string {
	out := ""
	games.ReverseIterate("", "", func(_ string, v any) bool {
		out += line(v.(*Game)) + "\n"
		return false
	})
	return out
}

// Line returns one game in the same shape as [Feed], or "" if there is no such
// game. A front-end polling one table asks for this, not for the whole feed.
func Line(id int) string {
	v := games.Get(key(id))
	if v == nil {
		return ""
	}
	return line(v.(*Game))
}

func line(g *Game) string {
	state := "live"
	switch {
	case g.Yellow == "" && g.Quit == "":
		state = "open"
	case g.Over():
		if w := g.Winner(); w != "" {
			state = w.String()
		} else if g.Yellow == "" {
			state = "withdrawn"
		} else {
			state = "draw"
		}
	}
	return itoa(g.ID) + "\t" + g.Red.String() + "\t" + g.Yellow.String() + "\t" + g.Moves + "\t" + state
}

package gno4

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/p/moul/gno4/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
)

// self is this realm's own gnoweb prefix, read from the package path it is
// running under.
//
// Not a constant, on purpose. The same source is deployed twice: once at
// r/moul/gno4 and once at r/moul/gno4/preview, the redeployable twin. A
// hardcoded "/r/moul/gno4" would send every link on the preview back to
// production, which reads as working and is the most confusing possible bug.
// txlink already does exactly this for the transaction links; this is the same
// rule applied to the page links.
func self() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

// Render is the product, not a debug view.
//
// Everything this realm knows is reachable from gnoweb with no wallet, no
// JavaScript and no front-end: the board is an inline SVG, every move is an
// ordinary link, and a game is a URL you can paste to somebody. The web app in
// web/ is a nicer way to do the same thing, never the only way.
//
// It is also deterministic. Nothing here reads the current height or the
// current time, only heights already recorded in state, which is what lets
// render_example_test.gno pin the output and turn a rendering regression into
// a red build instead of a permanently broken page.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "about":
		return renderAbout()
	case strings.HasPrefix(path, "g/"):
		return renderGame(strings.TrimPrefix(path, "g/"))
	case strings.HasPrefix(path, "u/"):
		return renderPlayer(strings.TrimPrefix(path, "u/"))
	}
	return "# Not found\n\nNo page at `" + md.EscapeText(path) + "`. [Back to the lobby](" + self() + ").\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Connect Four\n\n")
	b.WriteString("**The chain is the referee.** The rules live in a pure package that has never heard of a chain; ")
	b.WriteString("this realm owns the only three things that package cannot decide: who may move, when, and what everyone else gets to see.\n\n")
	b.WriteString(md.Link("Open a table", txlink.Call("Open")) + " and wait for someone, or join one below.\n\n")

	b.WriteString(section("Open tables", renderOpen()))
	b.WriteString(section("In play", renderLive()))
	b.WriteString(section("Finished", renderDone()))
	b.WriteString(section("Standings", renderStandings()))

	b.WriteString(md.HorizontalRule())
	b.WriteString(md.CollapsibleSection("How to play from a terminal", howTo()))
	b.WriteString("\n" + md.Link("What this realm is exploring", self()+":about") + "\n")
	return b.String()
}

func section(title, body string) string {
	if body == "" {
		return ""
	}
	return md.H2(title) + body + "\n"
}

func renderOpen() string {
	if len(open) == 0 {
		return ""
	}
	rows := "| table | opened by | at height | |\n|---|---|---|---|\n"
	for _, id := range open {
		g := mustGame(id)
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + itoa64(g.Opened) + " | " +
			md.Link("join", txlink.Call("Join", "id", itoa(id))) + " |\n"
	}
	return rows
}

func renderLive() string {
	if len(live) == 0 {
		return ""
	}
	rows := "| table | red | yellow | to move | moves |\n|---|---|---|---|---|\n"
	for _, id := range live {
		g := mustGame(id)
		board := g.Board()
		turn := g.Red
		if board.Turn() == gno4.Yellow {
			turn = g.Yellow
		}
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + player(g.Yellow) + " | " +
			disc(board.Turn()) + " " + player(turn) + " | " + itoa(board.MoveCount()) + " |\n"
	}
	return rows
}

func renderDone() string {
	if len(done) == 0 {
		return ""
	}
	rows := "| table | red | yellow | result |\n|---|---|---|---|\n"
	for _, id := range done {
		g := mustGame(id)
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + player(g.Yellow) + " | " + result(g) + " |\n"
	}
	return rows
}

func renderStandings() string {
	if records.Size() == 0 {
		return ""
	}
	rows := "| player | won | lost | drawn |\n|---|---|---|---|\n"
	records.Iterate("", "", func(k string, v any) bool {
		r := v.(*Record)
		rows += "| " + player(address(k)) + " | " + itoa(r.Wins) + " | " + itoa(r.Losses) + " | " + itoa(r.Draws) + " |\n"
		return false
	})
	return rows
}

func renderGame(raw string) string {
	id, ok := atoi(raw)
	if !ok || !games.Has(key(id)) {
		return "# Not found\n\nNo table numbered `" + md.EscapeText(raw) + "`. [Back to the lobby](" + self() + ").\n"
	}
	g := mustGame(id)
	board := g.Board()

	var b strings.Builder
	b.WriteString("# Table " + itoa(id) + "\n\n")
	b.WriteString(board.Image("Connect Four, table "+itoa(id)) + "\n\n")
	b.WriteString(status(g, board) + "\n\n")

	if !g.Over() && g.Yellow != "" {
		b.WriteString(moveRow(id, board) + "\n\n")
		b.WriteString(md.Italic("Anyone may click, but the chain only accepts the player whose turn it is.") + "\n\n")
	}
	if g.Yellow == "" && g.Quit == "" {
		b.WriteString(md.Link("Take the yellow seat", txlink.Call("Join", "id", itoa(id))) + "\n\n")
	}

	b.WriteString(md.H2("Seats"))
	b.WriteString("| | player | record |\n|---|---|---|\n")
	b.WriteString("| 🔴 red | " + player(g.Red) + " | " + recordLine(g.Red) + " |\n")
	if g.Yellow == "" {
		b.WriteString("| 🟡 yellow | _open_ | |\n")
	} else {
		b.WriteString("| 🟡 yellow | " + player(g.Yellow) + " | " + recordLine(g.Yellow) + " |\n")
	}
	b.WriteString("\n")

	b.WriteString(md.H2("The game, in full"))
	b.WriteString("The whole match is its move list, one digit per move. ")
	b.WriteString("Replaying it reproduces this position exactly, which is why that string is the only thing stored on chain.\n\n")
	b.WriteString(md.CodeBlock(orDash(g.Moves)))

	if !g.Over() && board.MoveCount() > 0 {
		b.WriteString(md.CollapsibleSection("Spoiler: is anyone one move from winning?", threats(board)))
	}
	b.WriteString("\n" + md.Link("Back to the lobby", self()) + "\n")
	return b.String()
}

func renderPlayer(raw string) string {
	addr := address(raw)
	if !addr.IsValid() {
		return "# Not a player\n\n`" + md.EscapeText(raw) + "` is not an address. [Back to the lobby](" + self() + ").\n"
	}
	var b strings.Builder
	b.WriteString("# " + short(addr) + "\n\n")
	b.WriteString(md.Link(addr.String(), "/u/"+addr.String()) + "\n\n")
	b.WriteString("Record: " + recordLine(addr) + "\n\n")

	rows := ""
	games.ReverseIterate("", "", func(k string, v any) bool {
		g := v.(*Game)
		if g.Red != addr && g.Yellow != addr {
			return false
		}
		rows += "| " + gameLink(g.ID) + " | " + player(other(g, addr)) + " | " + result(g) + " |\n"
		return false
	})
	if rows != "" {
		b.WriteString(md.H2("Games"))
		b.WriteString("| table | against | result |\n|---|---|---|\n" + rows + "\n")
	}
	b.WriteString(md.Link("Back to the lobby", self()) + "\n")
	return b.String()
}

func renderAbout() string {
	return `# What this realm is exploring

This is one of four small games built to answer a single question: **what does a
web2.5 application on gno.land actually need to get right?** Not the game, the
scaffolding around it.

The engine is a pure package with no chain import, so its rules are testable
with no node. This realm owns authority and rendering, and nothing else. The
board you see is an SVG generated at render time and inlined as a data URI, so
it costs no storage and there is no asset to go missing. Every page here is
reachable with no wallet and no JavaScript.

There are two deployments of this same source: this one, and a ` + "`/preview`" + `
twin flagged ` + "`private = true`" + ` so it stays redeployable while the design
is still moving. A public path can never be redeployed, which makes the flag the
most consequential line in the whole repository.

The repository, the checklist it is written against, and the other three games:
[github.com/moul/gno4](https://github.com/moul/gno4).

` + md.Link("Back to the lobby", self()) + "\n"
}

// --- small helpers -------------------------------------------------------

func status(g *Game, board *gno4.Board) string {
	switch {
	case g.Quit != "":
		return md.Bold(short(g.Quit)+" resigned.") + " " + player(g.Winner()) + " takes it."
	case board.Winner() != gno4.Empty:
		return md.Bold(disc(board.Winner())+" "+short(g.Winner())+" wins.") +
			" In " + itoa(board.MoveCount()) + " moves."
	case board.Draw():
		return md.Bold("A draw.") + " Forty-two discs, no line of four."
	case g.Yellow == "":
		return md.Bold("Waiting for an opponent.")
	default:
		turn := g.Red
		if board.Turn() == gno4.Yellow {
			turn = g.Yellow
		}
		return md.Bold(disc(board.Turn())+" "+short(turn)+" to move.") + " Move " + itoa(board.MoveCount()+1) + "."
	}
}

// moveRow is the move menu: one link per playable column, in column order, so
// its position under the board matches the board itself.
func moveRow(id int, board *gno4.Board) string {
	cells := make([]string, 0, gno4.Cols)
	for col := 0; col < gno4.Cols; col++ {
		label := itoa(col + 1)
		if !board.CanDrop(col) {
			cells = append(cells, "·")
			continue
		}
		cells = append(cells, md.Link("⬇ "+label, txlink.Call("Play", "id", itoa(id), "col", label)))
	}
	return strings.Join(cells, " · ")
}

func threats(board *gno4.Board) string {
	out := ""
	for _, d := range []gno4.Disc{gno4.Red, gno4.Yellow} {
		if col := board.WinningMove(d); col >= 0 {
			out += "- " + disc(d) + " wins immediately by playing column " + itoa(col+1) + ".\n"
		}
	}
	if out == "" {
		return "Neither side can win on this move.\n"
	}
	return out
}

func gameLink(id int) string { return md.Link(itoa(id), self()+":g/"+itoa(id)) }

func player(addr address) string {
	if addr == "" {
		return "_nobody_"
	}
	return md.Link(short(addr), self()+":u/"+addr.String())
}

func short(addr address) string {
	s := addr.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func disc(d gno4.Disc) string {
	switch d {
	case gno4.Red:
		return "🔴"
	case gno4.Yellow:
		return "🟡"
	}
	return "⚫"
}

func result(g *Game) string {
	if !g.Over() {
		return "in play"
	}
	if w := g.Winner(); w != "" {
		if g.Quit != "" {
			return player(w) + " (resignation)"
		}
		return player(w)
	}
	if g.Yellow == "" {
		return "withdrawn"
	}
	return "draw"
}

func recordLine(addr address) string {
	w, l, d := RecordOf(addr)
	return itoa(w) + "W / " + itoa(l) + "L / " + itoa(d) + "D"
}

func other(g *Game, addr address) address {
	if g.Red == addr {
		return g.Yellow
	}
	return g.Red
}

func orDash(s string) string {
	if s == "" {
		return "(no moves yet)"
	}
	return s
}

// howTo prints the two commands that cover the whole game, against whichever
// path this realm is actually deployed at.
func howTo() string {
	pkg := runtime.ChainDomain() + strings.TrimPrefix(self(), "/")
	tail := " \\\n  -gas-fee 1000000ugnot -gas-wanted 2000000 -broadcast" +
		" -chainid " + runtime.ChainID() + " \\\n  -remote https://rpc.gno.land:443 YOURKEY\n"
	return "```sh\n" +
		"# open a table; the transaction's output carries the id\n" +
		"gnokey maketx call -pkgpath " + pkg + " -func Open" + tail +
		"\n" +
		"# drop a disc into column 4 of table 7\n" +
		"gnokey maketx call -pkgpath " + pkg + " -func Play -args 7 -args 4" + tail +
		"```\n" +
		"\nThose gas numbers are a starting point, not a measurement. Simulate first: " +
		"drop `-broadcast` and the node answers with what the call actually costs.\n"
}

func itoa64(n int64) string { return itoa(int(n)) }

func atoi(s string) (int, bool) {
	if s == "" || len(s) > 9 {
		return 0, false
	}
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
	}
	return n, true
}

// Package gno4 is Connect Four with the chain as the referee.
//
// The rules live in [p/moul/gno4](/p/moul/gno4/v0), which knows nothing about
// the chain. This realm owns the three things a pure engine cannot: who may
// move, when, and what the world gets to see. That split is the whole design,
// and it is why the engine has 14 tests that need no node.
//
// Nothing here is a wager. A game holds no coins, so there is no escrow, no
// payout and no abandoned-table timeout to get wrong. Money is a second design
// and not a flag on this one.
package gno4

import (
	"chain/runtime"
	"errors"

	"gno.land/p/moul/gno4/v0"
	"gno.land/p/nt/avl/v0"
)

// Game is one table.
//
// The position is NOT stored: Moves is, and the board is replayed from it on
// demand. Three reasons, in the order they matter. The move list is the whole
// game in at most 42 bytes, so storage is minimal and bounded. It is the
// engine's own canonical form, so no second encoder can disagree with it. And
// an engine change never needs a state migration, because the only thing on
// chain is the input, which no engine version can reinterpret.
type Game struct {
	ID      int
	Red     address
	Yellow  address // zero while the table is open
	Moves   string  // gno4.Board.Encode()
	Opened  int64   // block height
	Touched int64   // block height of the last move
	Quit    address // whoever resigned, zero otherwise
}

// Record is a player's standing. Rating is deliberately absent: an Elo needs a
// K factor, a provisional period and an answer for resignations, and every one
// of those is a policy argument that would outlive the three lines of code.
type Record struct {
	Wins, Losses, Draws int
}

var (
	games   avl.Tree // padded id -> *Game
	records avl.Tree // address -> *Record
	nextID  = 1

	// open and live are id lists kept in most-recent-first order. An avl walk
	// could derive both, but it would walk every game ever played to render a
	// page that shows ten, and that cost grows forever.
	open []int
	live []int
	done []int
)

const doneKept = 20 // how many finished games the home page remembers

var (
	ErrNoSuchGame  = errors.New("gno4: no such game")
	ErrNotOpen     = errors.New("gno4: that table is not open")
	ErrOwnGame     = errors.New("gno4: you cannot play yourself")
	ErrNotYours    = errors.New("gno4: you are not in this game")
	ErrNotYourTurn = errors.New("gno4: not your turn")
	ErrFinished    = errors.New("gno4: that game is over")
)

// Open starts a table anyone may join. The caller takes red and moves first.
func Open(cur realm) int {
	caller := cur.Previous().Address()
	g := &Game{
		ID:     nextID,
		Red:    caller,
		Opened: runtime.ChainHeight(),
	}
	nextID++
	games.Set(key(g.ID), g)
	open = prepend(open, g.ID)
	return g.ID
}

// Join takes the yellow seat of an open table.
func Join(cur realm, id int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Yellow != "" {
		panic(ErrNotOpen)
	}
	if g.Red == caller {
		panic(ErrOwnGame)
	}
	g.Yellow = caller
	g.Touched = runtime.ChainHeight()
	open = remove(open, id)
	live = prepend(live, id)
}

// Play drops the caller's disc into col, counted from 1.
//
// Every refusal below is a rule the engine cannot enforce, because the engine
// has no idea who is calling. The engine still owns "is that column legal",
// and Drop is what answers it.
func Play(cur realm, id, col int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Over() {
		panic(ErrFinished)
	}
	if g.Yellow == "" {
		panic(ErrNotOpen)
	}
	b := g.Board()
	var seat address
	if b.Turn() == gno4.Red {
		seat = g.Red
	} else {
		seat = g.Yellow
	}
	if caller != g.Red && caller != g.Yellow {
		panic(ErrNotYours)
	}
	if caller != seat {
		panic(ErrNotYourTurn)
	}
	if _, err := b.Drop(col - 1); err != nil {
		panic(err)
	}
	g.Moves = b.Encode()
	g.Touched = runtime.ChainHeight()
	if b.Over() {
		finish(g, b.Winner())
	}
}

// Resign concedes. A game nobody resigns and nobody finishes stays live
// forever; that is a known hole, and a timeout is the fix, not a cron.
func Resign(cur realm, id int) {
	g := mustGame(id)
	caller := cur.Previous().Address()
	if g.Over() {
		panic(ErrFinished)
	}
	if caller != g.Red && caller != g.Yellow {
		panic(ErrNotYours)
	}
	g.Quit = caller
	g.Touched = runtime.ChainHeight()
	if g.Yellow == "" {
		// An open table nobody joined: withdraw it, and score nothing.
		open = remove(open, id)
		done = trim(prepend(done, id))
		return
	}
	winner := gno4.Red
	if caller == g.Red {
		winner = gno4.Yellow
	}
	finish(g, winner)
}

func finish(g *Game, winner gno4.Disc) {
	live = remove(live, g.ID)
	done = trim(prepend(done, g.ID))
	switch winner {
	case gno4.Red:
		record(g.Red).Wins++
		record(g.Yellow).Losses++
	case gno4.Yellow:
		record(g.Yellow).Wins++
		record(g.Red).Losses++
	default:
		record(g.Red).Draws++
		record(g.Yellow).Draws++
	}
}

// Board replays the move list. It never returns nil and never panics: a stored
// encoding that no longer decodes would make the game's page unreadable
// forever, so it degrades to an empty board instead.
func (g *Game) Board() *gno4.Board {
	b, err := gno4.Decode(g.Moves)
	if err != nil {
		return gno4.New()
	}
	return b
}

// Over reports whether the game is settled, by the rules or by a resignation.
func (g *Game) Over() bool { return g.Quit != "" || g.Board().Over() }

// Winner returns the winning seat, or the zero address on a draw, an open
// table or a game still in play.
func (g *Game) Winner() address {
	if g.Quit != "" {
		if g.Quit == g.Red {
			return g.Yellow
		}
		return g.Red
	}
	switch g.Board().Winner() {
	case gno4.Red:
		return g.Red
	case gno4.Yellow:
		return g.Yellow
	}
	return ""
}

// GameOf returns a copy of one game's public facts, for another realm or an
// off-chain reader that wants state rather than a rendered page.
//
// It returns values, not the *Game: this realm is private = true, so handing
// out a pointer into its own storage is the one thing that cannot be undone
// later.
func GameOf(id int) (red, yellow address, moves string, over bool) {
	v := games.Get(key(id))
	if v == nil {
		return "", "", "", false
	}
	g := v.(*Game)
	return g.Red, g.Yellow, g.Moves, g.Over()
}

// RecordOf returns a player's standing.
func RecordOf(addr address) (wins, losses, draws int) {
	v := records.Get(addr.String())
	if v == nil {
		return 0, 0, 0
	}
	r := v.(*Record)
	return r.Wins, r.Losses, r.Draws
}

func mustGame(id int) *Game {
	v := games.Get(key(id))
	if v == nil {
		panic(ErrNoSuchGame)
	}
	return v.(*Game)
}

func record(addr address) *Record {
	if v := records.Get(addr.String()); v != nil {
		return v.(*Record)
	}
	r := &Record{}
	records.Set(addr.String(), r)
	return r
}

// key zero-pads an id so avl's byte ordering is numeric ordering. ufmt has no
// width verb, which is why this is five lines instead of one.
func key(id int) string {
	s := itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	out := ""
	for n > 0 {
		out = string(rune('0'+n%10)) + out
		n /= 10
	}
	if neg {
		out = "-" + out
	}
	return out
}

func prepend(list []int, id int) []int {
	return append([]int{id}, list...)
}

func remove(list []int, id int) []int {
	out := make([]int, 0, len(list))
	for _, v := range list {
		if v != id {
			out = append(out, v)
		}
	}
	return out
}

func trim(list []int) []int {
	if len(list) > doneKept {
		return list[:doneKept]
	}
	return list
}

// Feed returns every game this realm knows, one per line, newest first:
//
//	<id>\t<red>\t<yellow>\t<moves>\t<state>
//
// where state is open, live, or the address that won, or "draw".
//
// A realm that only renders markdown forces its own front-end to scrape the
// page it renders, and then a wording change breaks the app. So there are two
// views of the same state: Render for people, Feed for programs. Neither is
// derived from the other, both are derived from the state, and the machine one
// is the cheap one to keep stable.
func Feed() string {
	out := ""
	games.ReverseIterate("", "", func(_ string, v any) bool {
		out += line(v.(*Game)) + "\n"
		return false
	})
	return out
}

// Line returns one game in the same shape as [Feed], or "" if there is no such
// game. A front-end polling one table asks for this, not for the whole feed.
func Line(id int) string {
	v := games.Get(key(id))
	if v == nil {
		return ""
	}
	return line(v.(*Game))
}

func line(g *Game) string {
	state := "live"
	switch {
	case g.Yellow == "" && g.Quit == "":
		state = "open"
	case g.Over():
		if w := g.Winner(); w != "" {
			state = w.String()
		} else if g.Yellow == "" {
			state = "withdrawn"
		} else {
			state = "draw"
		}
	}
	return itoa(g.ID) + "\t" + g.Red.String() + "\t" + g.Yellow.String() + "\t" + g.Moves + "\t" + state
}

package gno4

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/p/moul/gno4/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
)

// self is this realm's own gnoweb prefix, read from the package path it is
// running under.
//
// Not a constant, on purpose. The same source is deployed twice: once at
// r/moul/gno4 and once at r/moul/gno4/preview, the redeployable twin. A
// hardcoded "/r/moul/gno4" would send every link on the preview back to
// production, which reads as working and is the most confusing possible bug.
// txlink already does exactly this for the transaction links; this is the same
// rule applied to the page links.
func self() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

// Render is the product, not a debug view.
//
// Everything this realm knows is reachable from gnoweb with no wallet, no
// JavaScript and no front-end: the board is an inline SVG, every move is an
// ordinary link, and a game is a URL you can paste to somebody. The web app in
// web/ is a nicer way to do the same thing, never the only way.
//
// It is also deterministic. Nothing here reads the current height or the
// current time, only heights already recorded in state, which is what lets
// render_example_test.gno pin the output and turn a rendering regression into
// a red build instead of a permanently broken page.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "about":
		return renderAbout()
	case strings.HasPrefix(path, "g/"):
		return renderGame(strings.TrimPrefix(path, "g/"))
	case strings.HasPrefix(path, "u/"):
		return renderPlayer(strings.TrimPrefix(path, "u/"))
	}
	return "# Not found\n\nNo page at `" + md.EscapeText(path) + "`. [Back to the lobby](" + self() + ").\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Connect Four\n\n")
	b.WriteString("**The chain is the referee.** The rules live in a pure package that has never heard of a chain; ")
	b.WriteString("this realm owns the only three things that package cannot decide: who may move, when, and what everyone else gets to see.\n\n")
	b.WriteString(md.Link("Open a table", txlink.Call("Open")) + " and wait for someone, or join one below.\n\n")

	b.WriteString(section("Open tables", renderOpen()))
	b.WriteString(section("In play", renderLive()))
	b.WriteString(section("Finished", renderDone()))
	b.WriteString(section("Standings", renderStandings()))

	b.WriteString(md.HorizontalRule())
	b.WriteString(md.CollapsibleSection("How to play from a terminal", howTo()))
	b.WriteString("\n" + md.Link("What this realm is exploring", self()+":about") + "\n")
	return b.String()
}

func section(title, body string) string {
	if body == "" {
		return ""
	}
	return md.H2(title) + body + "\n"
}

func renderOpen() string {
	if len(open) == 0 {
		return ""
	}
	rows := "| table | opened by | at height | |\n|---|---|---|---|\n"
	for _, id := range open {
		g := mustGame(id)
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + itoa64(g.Opened) + " | " +
			md.Link("join", txlink.Call("Join", "id", itoa(id))) + " |\n"
	}
	return rows
}

func renderLive() string {
	if len(live) == 0 {
		return ""
	}
	rows := "| table | red | yellow | to move | moves |\n|---|---|---|---|---|\n"
	for _, id := range live {
		g := mustGame(id)
		board := g.Board()
		turn := g.Red
		if board.Turn() == gno4.Yellow {
			turn = g.Yellow
		}
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + player(g.Yellow) + " | " +
			disc(board.Turn()) + " " + player(turn) + " | " + itoa(board.MoveCount()) + " |\n"
	}
	return rows
}

func renderDone() string {
	if len(done) == 0 {
		return ""
	}
	rows := "| table | red | yellow | result |\n|---|---|---|---|\n"
	for _, id := range done {
		g := mustGame(id)
		rows += "| " + gameLink(id) + " | " + player(g.Red) + " | " + player(g.Yellow) + " | " + result(g) + " |\n"
	}
	return rows
}

func renderStandings() string {
	if records.Size() == 0 {
		return ""
	}
	rows := "| player | won | lost | drawn |\n|---|---|---|---|\n"
	records.Iterate("", "", func(k string, v any) bool {
		r := v.(*Record)
		rows += "| " + player(address(k)) + " | " + itoa(r.Wins) + " | " + itoa(r.Losses) + " | " + itoa(r.Draws) + " |\n"
		return false
	})
	return rows
}

func renderGame(raw string) string {
	id, ok := atoi(raw)
	if !ok || !games.Has(key(id)) {
		return "# Not found\n\nNo table numbered `" + md.EscapeText(raw) + "`. [Back to the lobby](" + self() + ").\n"
	}
	g := mustGame(id)
	board := g.Board()

	var b strings.Builder
	b.WriteString("# Table " + itoa(id) + "\n\n")
	b.WriteString(board.Image("Connect Four, table "+itoa(id)) + "\n\n")
	b.WriteString(status(g, board) + "\n\n")

	if !g.Over() && g.Yellow != "" {
		b.WriteString(moveRow(id, board) + "\n\n")
		b.WriteString(md.Italic("Anyone may click, but the chain only accepts the player whose turn it is.") + "\n\n")
	}
	if g.Yellow == "" && g.Quit == "" {
		b.WriteString(md.Link("Take the yellow seat", txlink.Call("Join", "id", itoa(id))) + "\n\n")
	}

	b.WriteString(md.H2("Seats"))
	b.WriteString("| | player | record |\n|---|---|---|\n")
	b.WriteString("| 🔴 red | " + player(g.Red) + " | " + recordLine(g.Red) + " |\n")
	if g.Yellow == "" {
		b.WriteString("| 🟡 yellow | _open_ | |\n")
	} else {
		b.WriteString("| 🟡 yellow | " + player(g.Yellow) + " | " + recordLine(g.Yellow) + " |\n")
	}
	b.WriteString("\n")

	b.WriteString(md.H2("The game, in full"))
	b.WriteString("The whole match is its move list, one digit per move. ")
	b.WriteString("Replaying it reproduces this position exactly, which is why that string is the only thing stored on chain.\n\n")
	b.WriteString(md.CodeBlock(orDash(g.Moves)))

	if !g.Over() && board.MoveCount() > 0 {
		b.WriteString(md.CollapsibleSection("Spoiler: is anyone one move from winning?", threats(board)))
	}
	b.WriteString("\n" + md.Link("Back to the lobby", self()) + "\n")
	return b.String()
}

func renderPlayer(raw string) string {
	addr := address(raw)
	if !addr.IsValid() {
		return "# Not a player\n\n`" + md.EscapeText(raw) + "` is not an address. [Back to the lobby](" + self() + ").\n"
	}
	var b strings.Builder
	b.WriteString("# " + short(addr) + "\n\n")
	b.WriteString(md.Link(addr.String(), "/u/"+addr.String()) + "\n\n")
	b.WriteString("Record: " + recordLine(addr) + "\n\n")

	rows := ""
	games.ReverseIterate("", "", func(k string, v any) bool {
		g := v.(*Game)
		if g.Red != addr && g.Yellow != addr {
			return false
		}
		rows += "| " + gameLink(g.ID) + " | " + player(other(g, addr)) + " | " + result(g) + " |\n"
		return false
	})
	if rows != "" {
		b.WriteString(md.H2("Games"))
		b.WriteString("| table | against | result |\n|---|---|---|\n" + rows + "\n")
	}
	b.WriteString(md.Link("Back to the lobby", self()) + "\n")
	return b.String()
}

func renderAbout() string {
	return `# What this realm is exploring

This is one of four small games built to answer a single question: **what does a
web2.5 application on gno.land actually need to get right?** Not the game, the
scaffolding around it.

The engine is a pure package with no chain import, so its rules are testable
with no node. This realm owns authority and rendering, and nothing else. The
board you see is an SVG generated at render time and inlined as a data URI, so
it costs no storage and there is no asset to go missing. Every page here is
reachable with no wallet and no JavaScript.

There are two deployments of this same source: this one, and a ` + "`/preview`" + `
twin flagged ` + "`private = true`" + ` so it stays redeployable while the design
is still moving. A public path can never be redeployed, which makes the flag the
most consequential line in the whole repository.

The repository, the checklist it is written against, and the other three games:
[github.com/moul/gno4](https://github.com/moul/gno4).

` + md.Link("Back to the lobby", self()) + "\n"
}

// --- small helpers -------------------------------------------------------

func status(g *Game, board *gno4.Board) string {
	switch {
	case g.Quit != "":
		return md.Bold(short(g.Quit)+" resigned.") + " " + player(g.Winner()) + " takes it."
	case board.Winner() != gno4.Empty:
		return md.Bold(disc(board.Winner())+" "+short(g.Winner())+" wins.") +
			" In " + itoa(board.MoveCount()) + " moves."
	case board.Draw():
		return md.Bold("A draw.") + " Forty-two discs, no line of four."
	case g.Yellow == "":
		return md.Bold("Waiting for an opponent.")
	default:
		turn := g.Red
		if board.Turn() == gno4.Yellow {
			turn = g.Yellow
		}
		return md.Bold(disc(board.Turn())+" "+short(turn)+" to move.") + " Move " + itoa(board.MoveCount()+1) + "."
	}
}

// moveRow is the move menu: one link per playable column, in column order, so
// its position under the board matches the board itself.
func moveRow(id int, board *gno4.Board) string {
	cells := make([]string, 0, gno4.Cols)
	for col := 0; col < gno4.Cols; col++ {
		label := itoa(col + 1)
		if !board.CanDrop(col) {
			cells = append(cells, "·")
			continue
		}
		cells = append(cells, md.Link("⬇ "+label, txlink.Call("Play", "id", itoa(id), "col", label)))
	}
	return strings.Join(cells, " · ")
}

func threats(board *gno4.Board) string {
	out := ""
	for _, d := range []gno4.Disc{gno4.Red, gno4.Yellow} {
		if col := board.WinningMove(d); col >= 0 {
			out += "- " + disc(d) + " wins immediately by playing column " + itoa(col+1) + ".\n"
		}
	}
	if out == "" {
		return "Neither side can win on this move.\n"
	}
	return out
}

func gameLink(id int) string { return md.Link(itoa(id), self()+":g/"+itoa(id)) }

func player(addr address) string {
	if addr == "" {
		return "_nobody_"
	}
	return md.Link(short(addr), self()+":u/"+addr.String())
}

func short(addr address) string {
	s := addr.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func disc(d gno4.Disc) string {
	switch d {
	case gno4.Red:
		return "🔴"
	case gno4.Yellow:
		return "🟡"
	}
	return "⚫"
}

func result(g *Game) string {
	if !g.Over() {
		return "in play"
	}
	if w := g.Winner(); w != "" {
		if g.Quit != "" {
			return player(w) + " (resignation)"
		}
		return player(w)
	}
	if g.Yellow == "" {
		return "withdrawn"
	}
	return "draw"
}

func recordLine(addr address) string {
	w, l, d := RecordOf(addr)
	return itoa(w) + "W / " + itoa(l) + "L / " + itoa(d) + "D"
}

func other(g *Game, addr address) address {
	if g.Red == addr {
		return g.Yellow
	}
	return g.Red
}

func orDash(s string) string {
	if s == "" {
		return "(no moves yet)"
	}
	return s
}

// howTo prints the two commands that cover the whole game, against whichever
// path this realm is actually deployed at.
func howTo() string {
	pkg := runtime.ChainDomain() + strings.TrimPrefix(self(), "/")
	tail := " \\\n  -gas-fee 1000000ugnot -gas-wanted 2000000 -broadcast" +
		" -chainid " + runtime.ChainID() + " \\\n  -remote https://rpc.gno.land:443 YOURKEY\n"
	return "```sh\n" +
		"# open a table; the transaction's output carries the id\n" +
		"gnokey maketx call -pkgpath " + pkg + " -func Open" + tail +
		"\n" +
		"# drop a disc into column 4 of table 7\n" +
		"gnokey maketx call -pkgpath " + pkg + " -func Play -args 7 -args 4" + tail +
		"```\n" +
		"\nThose gas numbers are a starting point, not a measurement. Simulate first: " +
		"drop `-broadcast` and the node answers with what the call actually costs.\n"
}

func itoa64(n int64) string { return itoa(int(n)) }

func atoi(s string) (int, bool) {
	if s == "" || len(s) > 9 {
		return 0, false
	}
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
	}
	return n, true
}

// Package gsdash renders one address's whole GnoSwap footprint on chain, with
// no indexer and no off-chain query: balances, liquidity positions, what each
// one is worth right now, and what it has earned but not collected.
//
// It reads GnoSwap through the unversioned proxy paths (r/gnoswap/position and
// friends) rather than their /vN implementations, so a GnoSwap implementation
// upgrade does not reach this realm.
package gsdash

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/gnft"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/gov/xgns"
	"gno.land/r/gnoswap/position"
	"gno.land/r/gnoswap/staker"
)

// scanWindow is how many stored position records one page walks.
//
// There is no address-to-positions index anywhere in GnoSwap: gnft is a plain
// grc721 with no enumerable extension, so the only way to find an address's
// positions is to walk the records and ask each one who owns it. GnoSwap's own
// position realm renders a keyed lookup and says out loud that it "does not
// enumerate positions", which is the same ceiling talking. Queries get
// 3,000,000,000 gas (maxGasQuery, gno.land/pkg/sdk/vm/keeper.go), so the walk
// is paged rather than unbounded, and the page footer links the next one.
const scanWindow = 250

// stakerPath is the realm that custodies a staked position's NFT. Staking
// transfers the token to it, so for anything staked the grc721 owner is this
// address and not a person: see resolveOwner.
const stakerPath = "gno.land/r/gnoswap/staker"

// Render serves three routes: the index, an address page, and the next page of
// an address whose records did not fit in one scan window.
//
//	""                  the index
//	"g1..."             that address, scanning from record 0
//	"g1.../from/500"    the same, scanning from record 500
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}

	addrPart, offset, ok := parsePath(path)
	if !ok {
		return ui.Empty("Not a route. Try `" + shortSelf + ":g1...`.")
	}
	addr := address(addrPart)
	if !addr.IsValid() {
		// Escaped rather than echoed: the path is whatever the reader typed.
		return ui.Empty("Not a valid address: " + ui.Inline(addrPart))
	}
	return renderAddress(addr, offset)
}

// shortSelf is this realm's own render prefix, used in the links it prints.
const shortSelf = "/r/moul/x/gsdash/v0"

func renderIndex() string {
	s := "# GnoSwap dashboard\n\n"
	s += "Everything one address has on GnoSwap, read live from the chain: GNS and xGNS " +
		"balances, every liquidity position with what it holds right now, the fees it has " +
		"accrued, and the emission rewards waiting to be collected.\n\n"
	s += ufmt.Sprintf("Open an address: `%s:g1...`\n\n", shortSelf)

	t := ui.NewTable("What", "Now")
	t.Row("Stored position records", ufmt.Sprintf("%d", position.GetPositions().Size()))
	t.Row("Position NFTs in circulation", ufmt.Sprintf("%d", gnft.TotalSupply()))
	t.Row("Records walked per page", ufmt.Sprintf("%d", scanWindow))
	s += t.String()

	s += "\nRecords include burned positions, so the count is not a count of live liquidity.\n"
	return s
}

func renderAddress(addr address, offset int) string {
	s := ufmt.Sprintf("# %s\n\n", ui.AddrFull(addr))

	nfts, err := gnft.BalanceOf(addr)
	if err != nil {
		nfts = 0
	}
	t := ui.NewTable("GNS", "xGNS", "Position NFTs held")
	t.Row(
		ufmt.Sprintf("%d", gns.BalanceOf(addr)),
		ufmt.Sprintf("%d", xgns.BalanceOf(addr)),
		ufmt.Sprintf("%d", nfts),
	)
	s += t.String() + "\n"

	s += ufmt.Sprintf("## Positions\n\nRecords %d to %d of %d.\n\n",
		offset, offset+scanWindow, position.GetPositions().Size())
	s += renderPositions(addr, offset)

	if next := offset + scanWindow; next < position.GetPositions().Size() {
		s += ufmt.Sprintf("\n[Next %d records](%s:%s/from/%d)\n", scanWindow, shortSelf, addr.String(), next)
	}
	return s
}

// renderPositions walks one window of the position records and prints the rows
// belonging to addr.
//
// The walk is deliberately cheap per record and expensive per hit: identifying
// the owner is one or two tree lookups, while the price math behind IsInRange,
// the token balances and the unclaimed fees costs far more. Only a row that is
// actually printed pays for it.
func renderPositions(addr address, offset int) string {
	t := ui.NewTable("ID", "Pool", "Ticks", "Liquidity", "In range", "Holds", "Uncollected fees", "Staked", "Reward")

	position.GetPositions().IterateByOffset(offset, scanWindow, func(key string, _ any) bool {
		id, err := strconv.ParseUint(key, 10, 64)
		if err != nil {
			return false
		}
		owner, staked, ok := resolveOwner(id)
		if !ok || owner != addr {
			return false
		}
		t.Row(row(id, staked)...)
		return false
	})

	return t.OrEmpty("No positions in this window.")
}

// row is the expensive half: everything here reads pool price state or recomputes
// a fee, so it runs for a matched position and never for a scanned one.
func row(id uint64, staked bool) []string {
	poolKey, _ := position.GetPositionPoolKey(id)
	lower, upper, _ := position.GetPositionTicks(id)
	liquidity, _ := position.GetPositionLiquidity(id)
	inRange, _ := position.IsInRange(id)
	amount0, amount1, _ := position.GetPositionTokenBalances(id)
	fee0, fee1, _ := position.GetUnclaimedFee(id)

	reward := "-"
	if staked {
		if r, err := staker.CollectableEmissionReward(id); err == nil {
			reward = ufmt.Sprintf("%d", r)
		}
	}

	return []string{
		ufmt.Sprintf("%d", id),
		ui.Cell(shortPool(poolKey)),
		ufmt.Sprintf("%d to %d", lower, upper),
		ui.Cell(liquidity),
		yesNo(inRange),
		ufmt.Sprintf("%d / %d", amount0, amount1),
		ui.Cell(fee0) + " / " + ui.Cell(fee1),
		yesNo(staked),
		reward,
	}
}

// resolveOwner answers who a position really belongs to, and whether it is staked.
//
// Staking transfers the position NFT to the staker realm, so for every staked
// position the grc721 owner is that realm's address and not the person's. A
// dashboard that trusts the NFT owner alone shows an empty page to everyone who
// staked, which is most of them. The deposit record is what still names the
// person.
func resolveOwner(id uint64) (owner address, staked bool, ok bool) {
	held, err := position.GetPositionOwner(id)
	if err != nil {
		return "", false, false
	}
	if held != chain.PackageAddress(stakerPath) {
		return held, false, true
	}
	deposited, err := staker.GetDepositOwner(id)
	if err != nil {
		// Custodied by the staker with no deposit behind it: in flight, or a
		// record this realm does not understand. Better to say nothing than to
		// attribute it to the staker realm as if it were a user.
		return "", true, false
	}
	return deposited, true, true
}

// parsePath splits an address route from its optional scan offset.
func parsePath(path string) (addr string, offset int, ok bool) {
	addr, rest, found := strings.Cut(path, "/")
	if !found {
		return addr, 0, true
	}
	after, found := strings.CutPrefix(rest, "from/")
	if !found {
		return "", 0, false
	}
	n, err := strconv.Atoi(after)
	if err != nil || n < 0 {
		return "", 0, false
	}
	return addr, n, true
}

// shortPool turns a pool key ("<token0 path>.<symbol>:<token1 path>.<symbol>:<fee>")
// into something that fits a table cell.
func shortPool(poolKey string) string {
	parts := strings.Split(poolKey, ":")
	if len(parts) != 3 {
		return poolKey
	}
	return symbolOf(parts[0]) + "/" + symbolOf(parts[1]) + " " + parts[2]
}

// symbolOf takes the symbol off a GnoSwap token key, which is the grc20 registry
// form "<pkgpath>.<Symbol>".
func symbolOf(tokenKey string) string {
	if i := strings.LastIndex(tokenKey, "."); i >= 0 {
		return tokenKey[i+1:]
	}
	return tokenKey
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

package gsdash

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"

	// GnoSwap's unversioned paths are proxies: the facade holds no logic and
	// panics with "implementation is not initialized" until some version has
	// registered itself. On chain that happened long ago; in a test VM nothing
	// has, so these blank imports run each implementation's init, which calls
	// RegisterInitializer, and the version manager activates the first one it
	// sees. Importing them here rather than from the realm keeps them out of
	// what gets deployed: the realm only ever names the proxy.
	_ "gno.land/r/gnoswap/pool/v1"
	_ "gno.land/r/gnoswap/position/v1"
	_ "gno.land/r/gnoswap/staker/v1"
)

// someone is a well-formed address with nothing on GnoSwap, which is what every
// address looks like in a fresh test VM.
const someone = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"

func TestRenderIndexReadsTheProxies(t *testing.T) {
	out := Render("")
	uassert.True(t, len(out) > 0, "index renders")
	uassert.True(t, strings.Contains(out, "# GnoSwap dashboard"), "index has its heading")
	// Reaching this line at all is the point: Size() and TotalSupply() are
	// cross-realm reads through two different GnoSwap proxies, so an index that
	// renders proves both resolved to a live implementation.
	uassert.True(t, strings.Contains(out, "Stored position records"), "index read the position proxy")
	uassert.True(t, strings.Contains(out, "Position NFTs in circulation"), "index read the gnft realm")
}

func TestRenderAddressWithNothing(t *testing.T) {
	out := Render(someone)
	uassert.True(t, strings.Contains(out, someone), "the page names the address in full")
	uassert.True(t, strings.Contains(out, "No positions in this window."), "an empty window says so")
}

func TestRenderRejectsAMalformedAddress(t *testing.T) {
	out := Render("not-an-address")
	uassert.True(t, strings.Contains(out, "Not a valid address"), "a bad address is refused")
	uassert.False(t, strings.Contains(out, "## Positions"), "and no scan is run for it")
}

func TestRenderEscapesWhatTheReaderTyped(t *testing.T) {
	// The path is attacker-controlled: whatever is after the colon in the URL.
	// It must come back inert, never as a live link.
	out := Render("[click](https://evil.example)")
	uassert.False(t, strings.Contains(out, "](https://evil.example)"), "no live link survives")
}

func TestParsePath(t *testing.T) {
	tests := []struct {
		name       string
		path       string
		wantAddr   string
		wantOffset int
		wantOK     bool
	}{
		{"bare address", someone, someone, 0, true},
		{"with offset", someone + "/from/250", someone, 250, true},
		{"zero offset", someone + "/from/0", someone, 0, true},
		{"unknown segment", someone + "/nope", "", 0, false},
		{"offset not a number", someone + "/from/abc", "", 0, false},
		{"negative offset", someone + "/from/-1", "", 0, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			addr, offset, ok := parsePath(tt.path)
			uassert.Equal(t, tt.wantOK, ok)
			if !tt.wantOK {
				return
			}
			uassert.Equal(t, tt.wantAddr, addr)
			uassert.Equal(t, tt.wantOffset, offset)
		})
	}
}

func TestShortPool(t *testing.T) {
	tests := []struct {
		name string
		key  string
		want string
	}{
		{
			"a real pool key",
			"gno.land/r/gnoland/wugnot.wugnot:gno.land/r/gnoswap/gns.GNS:3000",
			"wugnot/GNS 3000",
		},
		{"not a pool key", "whatever", "whatever"},
		{"no symbol on a side", "a:b:100", "a/b 100"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			uassert.Equal(t, tt.want, shortPool(tt.key))
		})
	}
}

// ExampleRender pins the index as a fresh chain renders it: no positions, no
// NFTs, and the two proxy reads resolving to zero rather than panicking.
func ExampleRender() {
	println(Render(""))
	// Output:
	// # GnoSwap dashboard
	//
	// Everything one address has on GnoSwap, read live from the chain: GNS and xGNS balances, every liquidity position with what it holds right now, the fees it has accrued, and the emission rewards waiting to be collected.
	//
	// Open an address: `/r/moul/x/gsdash/v0:g1...`
