func TestPct(t *testing.T) {
	uassert.Equal(t, "12.34%", Pct(1234))
	uassert.Equal(t, "1%", Pct(100))
	uassert.Equal(t, "0.01%", Pct(1))
	uassert.Equal(t, "0%", Pct(0))
	uassert.Equal(t, "-12.34%", Pct(-1234))
