func TestPad(t *testing.T) {
	cases := []struct {
		v     int64
		width int
		want  string
	}{
		{7, 3, "007"},
		{123, 3, "123"},
		{1234, 3, "1234"},
		{0, 2, "00"},
		{7, 0, "7"},
