func TestPlural(t *testing.T) {
	uassert.Equal(t, "1 block", Plural(1, "block", ""))
	uassert.Equal(t, "2 blocks", Plural(2, "block", ""))
	uassert.Equal(t, "0 blocks", Plural(0, "block", ""))
	uassert.Equal(t, "2 mice", Plural(2, "mouse", "mice"))
	uassert.Equal(t, "-1 block", Plural(-1, "block", ""))
}

func TestBlocks(t *testing.T) {
	uassert.Equal(t, "now", Blocks(0))
	uassert.Equal(t, "1 block", Blocks(1))
	uassert.Equal(t, "9 blocks", Blocks(9))
	uassert.Equal(t, "~10 blocks", Blocks(15))
	uassert.Equal(t, "~1,200 blocks", Blocks(1234))
	uassert.Equal(t, "in the past", Blocks(-5))
}

// Truncate counts runes, so multi-byte text is never cut mid-character.
func TestTruncateCountsRunes(t *testing.T) {
	uassert.Equal(t, "hello", Truncate("hello", 10))
	uassert.Equal(t, "hell…", Truncate("hello!", 5))
	uassert.Equal(t, "…", Truncate("hello", 1))
	uassert.Equal(t, "", Truncate("hello", 0))
	uassert.Equal(t, "éé", Truncate("éé", 2))
	uassert.Equal(t, "é…", Truncate("ééé", 2)) // not sliced mid-rune
}

// TestCommaSurvivesTheInt64Minimum pins the defect v0 shipped. -n on
// math.MinInt64 is math.MinInt64, so FormatInt emitted its own sign and the
// neg branch prepended a second: v0 returned
// "--9,223,372,036,854,775,808". Break the mag split and this goes red.
func TestCommaSurvivesTheInt64Minimum(t *testing.T) {
	const minInt64 = -9223372036854775808
	uassert.Equal(t, "-9,223,372,036,854,775,808", Comma(minInt64))
	uassert.Equal(t, "9,223,372,036,854,775,807", Comma(9223372036854775807))
}

// TestCommaNeverDoublesTheSign is the invariant behind it, stated so a future
// rewrite cannot reintroduce the shape without failing.
func TestCommaNeverDoublesTheSign(t *testing.T) {
	const minInt64 = -9223372036854775808
	for _, n := range []int64{0, 1, -1, 999, -1000, 1234567, -1234567, minInt64} {
		s := Comma(n)
		if strings.HasPrefix(s, "--") || strings.Contains(s, "-,") {
			t.Errorf("Comma(%d) = %q", n, s)
		}
		if (n < 0) != strings.HasPrefix(s, "-") {
			t.Errorf("Comma(%d) = %q, sign disagrees with the input", n, s)
		}
	}
}

// Package envelope reads and forwards the coins a transaction attached to a
// call: the `-send` field of a `MsgCall`, credited to the called realm's address
// before a line of its code runs.
//
// It exists because "payable" is not a keyword in gno, it is a runtime fact. The
// VM rejects a `MsgCall` that carried coins the callee never looked at
// (gno.land/pkg/sdk/vm/keeper.go, `if !send.IsZero() && !*OriginSendObserved`),
// and reading the envelope is what counts as looking. So every realm that
// accepts payment writes the same three things by hand: read the amount, abort
// with something the caller can act on when it is zero or the wrong denom, and
// forward or keep it. This package is those three things.
//
// # Native coins are push-only, which is why this matters
//
// A realm cannot pull a native coin. `banker.SendCoins` panics unless the
// `from` address is the banker's own realm address, so there is no allowance
// and no `TransferFrom` for a native denom. The envelope is the entire inbound
// path: either the holder signs a bank send, or they attach coins to a call and
// the callee reads them here.
//
// That is also why a GRC20 needs `Approve` and a native coin does not. The GRC20
// grants standing authority to a spender; the envelope grants authority over one
// message and expires with it.
//
// # Who may forward, which is not about depth
//
// [Forward] mints a `BankerTypeOriginSend` banker, and `NewBanker` accepts that
// type only when `rlm.Previous().IsUserCall()` holds. `Realm.IsUserCall` is
// literally `pkgPath == ""` (gnovm/stdlibs/chain/runtime/frame.gno), so the test
// is about WHO entered the realm, not about how deep inside it you are:
//
//   - `maketx call` straight into the realm: fine, and the realm may pass its
//     `cur` down through as many of its own helpers as it likes. Measured at
//     three nested calls, and through a function value and a closure.
//   - realm A calls realm B, and B tries to forward: refused. B's previous is a
//     code realm, so the envelope it was handed is not B's to route.
//   - `maketx run`: refused. The run package is a code realm
//     (`<domain>/e/<addr>/run`), so `IsUserCall` is false there too, and every
//     payable function is therefore unreachable from a run script.
//
// The reading helpers have none of these conditions: they go through
// `unsafe.OriginSend()`, a context read that works anywhere, including inside a
// `Render`.
//
package envelope

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
)

// Amount returns how much of denom this message's envelope carried, and zero
// when it carried none. Reading it is what makes the call payable.
func Amount(denom string) int64 {
	return unsafe.OriginSend().AmountOf(denom)
}

// All returns the whole envelope, every denom in it.
//
// A call can be paid in several denoms at once, which is a property of the bank
// rather than of any realm: a `Coins` set holds up to 256 of them. A realm that
// only wants one should use [Only].
func All() chain.Coins {
	return unsafe.OriginSend()
}

// IsEmpty reports whether nothing was attached to this call.
func IsEmpty() bool {
	return len(unsafe.OriginSend()) == 0
}

// Require returns [Amount] and aborts when it is zero, with a message naming the
// flag the caller left out.
//
// The message is the point. "insufficient funds" sends somebody to their wallet;
// naming the denom and the flag sends them to the fix.
func Require(denom string) int64 {
	amount := Amount(denom)
	if amount <= 0 {
		panic("this call must be paid: attach coins with -send <amount>" + denom)
	}
	return amount
}

// RequireAtLeast is [Require] with a floor, and names both numbers when the
// envelope falls short.
func RequireAtLeast(denom string, min int64) int64 {
	amount := Require(denom)
	if amount < min {
		panic(ufmt.Sprintf("this call costs at least %d%s, the envelope carried %d",
			min, denom, amount))
	}
	return amount
}

// RequireExactly is [Require] for a fixed price, and refuses an overpayment as
// well as an underpayment.
//
// Refusing to be overpaid is the unusual half, and it is deliberate: a realm
// that silently keeps the excess has invented a fee nobody agreed to, and a
// realm that refunds it has to move coins back out, which is a second failure
// mode. Aborting costs the caller one transaction and nothing else.
func RequireExactly(denom string, price int64) int64 {
	amount := Require(denom)
	if amount != price {
		panic(ufmt.Sprintf("this call costs exactly %d%s, the envelope carried %d",
			price, denom, amount))
	}
	return amount
}

// Only is [Require] plus a refusal of anything else in the envelope.
//
// Use it wherever the realm has no code that would ever move a second denom,
// because coins it does not handle are coins stranded at its address forever:
// they are not refunded, and only the realm's own code can ever send them on.
func Only(denom string) int64 {
	amount := Require(denom)
	for _, coin := range unsafe.OriginSend() {
		if coin.Denom != denom {
			panic(ufmt.Sprintf("this call takes %s only, the envelope also carried %d%s",
				denom, coin.Amount, coin.Denom))
		}
	}
	return amount
}

// Forward sends coins from the calling realm's address to `to`, bounded by this
// message's envelope.
//
// The banker it mints can spend the envelope and nothing else: not the realm's
// own balance, not a previous message's payment. That is what makes a routing
// function safe to write, and it is enforced by the VM rather than by the code
// here (`ctx.OriginSend.IsAllGTE(spent)`).
//
// It must be reached from a call a USER made into this realm; see the package
// doc for what that rules out.
//
// The leading `_ int` is not decoration: a non-realm package may not declare a
// crossing function, so a `p/` helper that needs a realm handle threads it as a
// later parameter. That is the same shape `p/nt/grc20`'s tellers use, and gno
// refuses the file outright without it ("crossing function (realm first
// argument) declared in non-realm package").
//
// This function has no test in this package either, for the same reason it has
// that signature: minting the banker calls `rlm.Previous()`, and a `p/` test has
// no realm frame to walk ("frame not found: cannot seek beyond origin caller
// override"). It is exercised from `r/moul/x/nativeify`'s tests instead.
func Forward(_ int, rlm realm, to address, coins chain.Coins) {
	banker.NewBanker(banker.BankerTypeOriginSend, rlm).SendCoins(rlm.Address(), to, coins)
}

// ForwardAll forwards everything the envelope carried of denom, and returns it.
// It aborts when the envelope carried none, like [Require].
func ForwardAll(_ int, rlm realm, to address, denom string) int64 {
	amount := Require(denom)
	Forward(0, rlm, to, chain.NewCoins(chain.NewCoin(denom, amount)))
	return amount
}

// BalanceOf returns what addr holds of denom right now, straight from the bank.
//
// It takes an address rather than a realm handle because it needs no authority
// at all: a readonly banker is constructible from anywhere, including a Render.
// Pass `cur.Address()` for the realm's own balance, envelope included.
func BalanceOf(addr address, denom string) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

package envelope

import (
	"chain"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const (
	coin  = "/gno.land/r/moul/x/moultest/v0:moultest"
	other = "ugnot"
)

func pay(coins ...chain.Coin) {
	testing.SetOriginSend(chain.NewCoins(coins...))
}

func TestReadsAnEmptyEnvelope(cur realm, t *testing.T) {
	pay()
	uassert.True(t, IsEmpty())
	uassert.Equal(t, int64(0), Amount(coin))
	uassert.Equal(t, 0, len(All()))
	uassert.PanicsContains(t, cur, "must be paid", func() { Require(coin) })
}

func TestReadsAPaidEnvelope(cur realm, t *testing.T) {
	pay(chain.NewCoin(coin, 250))
	uassert.False(t, IsEmpty())
	uassert.Equal(t, int64(250), Amount(coin))
	uassert.Equal(t, int64(250), Require(coin))
	uassert.Equal(t, int64(0), Amount(other), "a denom that did not arrive reads zero")
	pay()
}

func TestFloorsAndPrices(cur realm, t *testing.T) {
	pay(chain.NewCoin(coin, 100))

	uassert.Equal(t, int64(100), RequireAtLeast(coin, 100), "the floor is inclusive")
	uassert.Equal(t, int64(100), RequireAtLeast(coin, 99))
	uassert.PanicsContains(t, cur, "costs at least 101", func() { RequireAtLeast(coin, 101) })

	uassert.Equal(t, int64(100), RequireExactly(coin, 100))
	uassert.PanicsContains(t, cur, "costs exactly 99", func() { RequireExactly(coin, 99) },
		"being overpaid is refused too, not quietly kept")
	uassert.PanicsContains(t, cur, "costs exactly 101", func() { RequireExactly(coin, 101) })
	pay()
}

func TestOnlyRefusesAMixedEnvelope(cur realm, t *testing.T) {
	pay(chain.NewCoin(coin, 100))
	uassert.Equal(t, int64(100), Only(coin))

	pay(chain.NewCoin(coin, 100), chain.NewCoin(other, 7))
	uassert.Equal(t, int64(100), Amount(coin), "the mixed envelope still reads fine")
	uassert.Equal(t, int64(7), Amount(other))
	uassert.PanicsContains(t, cur, "also carried 7ugnot", func() { Only(coin) })

	// Only still requires the denom it was asked about, mixed or not.
	pay(chain.NewCoin(other, 7))
	uassert.PanicsContains(t, cur, "must be paid", func() { Only(coin) })
	pay()
}

func TestRequireNamesTheFlagToFix(cur realm, t *testing.T) {
	// The abort is the realm's user interface at the moment somebody got it
	// wrong, so it carries the flag and the denom, not a status code.
	pay()
	uassert.PanicsContains(t, cur, "-send <amount>"+coin, func() { Require(coin) })
}

// Package accrual is stock that fills at a rate while nobody is playing: the
// resource field of an idle game, the warehouse of a 4X, anything whose state
// is a function of how long it has been left alone.
//
// The shape is always the same. Store what you had and when, and compute the
// rest on demand; a player who does nothing for a month costs nothing, and the
// realm needs no cron, no keeper and no per-block hook. That much is obvious.
// What is not obvious is that the obvious implementation is wrong in three
// ways, each of which has been observed in this repository rather than
// reasoned about.
//
// # 1. Re-anchoring to now makes acting more often pay
//
// Written naively, a claim advances the anchor to now and computes
// elapsed/Period whole periods of production. The division truncates, so every
// claim silently forfeits the part-period it lands in, and a player who claims
// twice forfeits twice. Run in reverse on a decaying stat it is worse than
// unfair, it is free: [r/moul/x/daily/tamagotchi] decayed by elapsed/2 and
// elapsed/3, so at elapsed == 1 it decayed by nothing at all, and feeding once
// per block made the pet immortal while every other cadence died inside 240
// blocks. It was fixed in #221.
//
// The invariant that rules it out is worth stating on its own, because it is
// the whole contract of this package:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)   for a <= b <= c
//
// How often you call must not change where you end up. [Rate.Advance] gets
// there by advancing the anchor only by the WHOLE periods it paid for, leaving
// the remainder on the clock rather than throwing it away. TestSplitInvariant
// asserts it over pseudo-random partitions rather than over a handful of
// hand-picked spans, because the hand-picked spans are exactly the ones a
// wrong implementation already passes.
//
// # 2. A view that does not share the write path's arithmetic drifts from it
//
// The same realm had a second copy of the decay for its Render, so the page
// showed a pet the next call would not honour. Two implementations of one rule
// means one of them is the stale one somebody acts on. Here there is one
// function: [Rate.At] is [Rate.Advance] with the anchor discarded, so a view
// cannot disagree with a write even in principle.
//
// # 3. A projection that is not closed form cannot be rendered at all
//
// Render runs under a query gas limit and may not write, so whatever it
// computes has to be bounded however long the player was away. Anything
// iterative, stepping a simulation once per block, is fine in a transaction
// and unusable in a page: the player who comes back after a month is exactly
// the one whose page times out. Everything here is O(1) in elapsed time, which
// is the property that makes a live-updating page possible, not an
// optimisation.
//
// Times are int64 and the unit is the caller's, block heights or unix seconds,
// as long as it is consistent. Prefer a timestamp: a block-height rate drifts
// in wall-clock terms every time the chain's block time moves, and gno.land's
// has moved from about 4.1s to 3.405s inside one month. Nothing here reads the
// chain, so a realm can test a year of its own economy without one.
//
// A game built on this package is at
// [r/moul/x/games/idle](/r/moul/x/games/idle/v0).
//
// [r/moul/x/daily/tamagotchi]: /r/moul/x/daily/tamagotchi/v0
package accrual

import "errors"

const maxInt64 = int64(9223372036854775807)

var (
	// ErrBadAmount is returned when the amount produced per period is not
	// positive. A zero rate is a bug in the caller, not a valid still life:
	// it makes Full unanswerable and every Advance a no-op.
	ErrBadAmount = errors.New("accrual: amount must be positive")
	// ErrBadPeriod is returned when the period is not positive.
	ErrBadPeriod = errors.New("accrual: period must be positive")
	// ErrBadCap is returned when the cap is negative. Zero is legal and
	// means unbounded.
	ErrBadCap = errors.New("accrual: cap must not be negative")
	// ErrNegativeStock is returned when the stock handed in is negative,
	// which would let a caller mint by going through zero.
	ErrNegativeStock = errors.New("accrual: stock must not be negative")
	// ErrBackwards is returned when now falls before the anchor. Time moving
	// backwards is a caller bug (a stored anchor from another clock, a test
	// that rewound), and silently treating it as zero elapsed would hide it.
	ErrBackwards = errors.New("accrual: now must not fall before the anchor")
	// ErrOverflow is returned when the arithmetic would wrap int64.
	ErrOverflow = errors.New("accrual: int64 overflow")
)

// Rate is production per unit of time, against a ceiling. Construct with New
// so the invariants are checked once instead of on every call.
type Rate struct {
	Amount int64 // produced each whole Period
	Period int64 // time units in one period
	Cap    int64 // ceiling on the stock; zero means unbounded
}

// New validates and returns a Rate. A zero cap means unbounded.
func New(amount, period, capacity int64) (Rate, error) {
	if amount <= 0 {
		return Rate{}, ErrBadAmount
	}
	if period <= 0 {
		return Rate{}, ErrBadPeriod
	}
	if capacity < 0 {
		return Rate{}, ErrBadCap
	}
	return Rate{Amount: amount, Period: period, Cap: capacity}, nil
}

// Advance returns the stock and the new anchor at time now, given stock held
// since anchor.
//
// The new anchor is NOT now. It is the anchor plus the whole periods actually
// paid out, so the part-period in progress stays on the clock and splitting a
// span into pieces yields exactly what advancing it in one go would:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)   for a <= b <= c
//
// Production past the cap is lost, which is what a cap is for. Saturation is
// idempotent, so it does not break the equality above, and it means a CAPPED
// rate can never return ErrOverflow: the answer is the cap however long the
// player was away. Only an uncapped rate can run out of int64.
func (r Rate) Advance(stock, anchor, now int64) (int64, int64, error) {
	if err := r.check(); err != nil {
		return 0, 0, err
	}
	if stock < 0 {
		return 0, 0, ErrNegativeStock
	}
	if now < anchor {
		return 0, 0, ErrBackwards
	}
	// now-anchor wraps only when the anchor is negative and now is far
	// enough above it. maxInt64+anchor is safe to compute precisely because
	// anchor is negative there.
	if anchor < 0 && now > maxInt64+anchor {
		return 0, 0, ErrOverflow
	}

	periods := (now - anchor) / r.Period

	// The anchor only moves by what was paid for. periods*r.Period cannot
	// overflow, it is at most now-anchor, and adding it back cannot pass now.
	newAnchor := anchor + periods*r.Period

	if r.Cap > 0 && stock >= r.Cap {
		return stock, newAnchor, nil
	}

	// Production is only computed when its exact value can matter. A capped
	// rate whose payout would wrap int64 has an answer regardless of what
	// that payout is, so it gets one instead of an error.
	if periods > maxInt64/r.Amount {
		return r.saturate(newAnchor)
	}
	produced := periods * r.Amount
	if produced > maxInt64-stock {
		return r.saturate(newAnchor)
	}

	total := stock + produced
	if r.Cap > 0 && total > r.Cap {
		total = r.Cap
	}
	return total, newAnchor, nil
}

// saturate answers an accrual too large for int64: the cap if there is one,
// and an error if there is not. A capped Rate therefore never overflows,
// which is the property that lets a realm size a warehouse without also
// having to bound its own lifetime.
func (r Rate) saturate(newAnchor int64) (int64, int64, error) {
	if r.Cap == 0 {
		return 0, 0, ErrOverflow
	}
	return r.Cap, newAnchor, nil
}

// At is Advance with the anchor discarded: the read-only view of the same
// arithmetic, for a Render that must not write. It is defined in terms of
// Advance on purpose, so a page can never show a number a write would not
// honour.
func (r Rate) At(stock, anchor, now int64) (int64, error) {
	got, _, err := r.Advance(stock, anchor, now)
	return got, err
}

// Full returns the time at which the stock first reaches the cap, for a realm
// that wants to tell a player when their production starts being wasted.
//
// An uncapped rate returns zero, meaning never. A stock already at or past the
// cap returns the anchor, meaning now.
func (r Rate) Full(stock, anchor int64) (int64, error) {
	if err := r.check(); err != nil {
		return 0, err
	}
	if stock < 0 {
		return 0, ErrNegativeStock
	}
	if r.Cap == 0 {
		return 0, nil
	}
	if stock >= r.Cap {
		return anchor, nil
	}

	// Whole periods needed to cover the shortfall, rounded UP: the cap is
	// reached by the payout that crosses it, not by the one before.
	need := r.Cap - stock
	periods := need / r.Amount
	if need%r.Amount != 0 {
		periods++
	}
	if periods > maxInt64/r.Period {
		return 0, ErrOverflow
	}
	span := periods * r.Period
	if span > maxInt64-anchor {
		return 0, ErrOverflow
	}
	return anchor + span, nil
}

// check rejects a zero Rate built by struct literal instead of New, so a
// caller that skipped the constructor gets the same error it would have.
func (r Rate) check() error {
	if r.Amount <= 0 {
		return ErrBadAmount
	}
	if r.Period <= 0 {
		return ErrBadPeriod
	}
	if r.Cap < 0 {
		return ErrBadCap
	}
	return nil
}

package accrual

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func mustNew(t *testing.T, amount, period, capacity int64) Rate {
	t.Helper()
	r, err := New(amount, period, capacity)
	uassert.NoError(t, err)
	return r
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		want                     error
	}{
		{"zero amount", 0, 60, 100, ErrBadAmount},
		{"negative amount", -1, 60, 100, ErrBadAmount},
		{"zero period", 1, 0, 100, ErrBadPeriod},
		{"negative period", 1, -60, 100, ErrBadPeriod},
		{"negative cap", 1, 60, -1, ErrBadCap},
		{"zero cap is unbounded", 1, 60, 0, nil},
		{"all positive", 5, 60, 100, nil},
	}
	for _, tc := range cases {
		_, err := New(tc.amount, tc.period, tc.capacity)
		if tc.want == nil {
			uassert.NoError(t, err, tc.name)
			continue
		}
		uassert.ErrorIs(t, err, tc.want, tc.name)
	}
}

func TestAdvance(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		stock, anchor, now       int64
		wantStock, wantAnchor    int64
	}{
		{"nothing elapsed", 1, 60, 0, 0, 1000, 1000, 0, 1000},
		{"less than one period", 1, 60, 0, 0, 1000, 1059, 0, 1000},
		{"exactly one period", 1, 60, 0, 0, 1000, 1060, 1, 1060},
		{"one period and change keeps the change", 1, 60, 0, 0, 1000, 1119, 1, 1060},
		{"ten periods", 3, 60, 0, 0, 1000, 1600, 30, 1600},
		{"adds to what was held", 3, 60, 0, 7, 1000, 1600, 37, 1600},
		{"saturates at the cap", 1, 60, 10, 0, 1000, 9000, 10, 8980},
		{"already full produces nothing", 1, 60, 10, 10, 1000, 9000, 10, 8980},
		{"over the cap is left alone", 1, 60, 10, 25, 1000, 9000, 25, 8980},
		{"uncapped keeps going", 1, 60, 0, 0, 0, 604800, 10080, 604800},
	}
	for _, tc := range cases {
		r := mustNew(t, tc.amount, tc.period, tc.capacity)
		gotStock, gotAnchor, err := r.Advance(tc.stock, tc.anchor, tc.now)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.wantStock, gotStock, tc.name+": stock")
		uassert.Equal(t, tc.wantAnchor, gotAnchor, tc.name+": anchor")
	}
}

// TestAnchorKeepsTheRemainder pins the one decision the whole package rests
// on: the new anchor is not now. Advancing to a time halfway through a period
// leaves that half on the clock, which is what makes splitting free.
func TestAnchorKeepsTheRemainder(t *testing.T) {
	r := mustNew(t, 1, 60, 0)
	_, anchor, err := r.Advance(0, 0, 599)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(540), anchor, "anchor must stop at the last whole period, not at now")
}

// TestSplitInvariant is the contract of this package:
//
//	Advance(s, a, c) == Advance(Advance(s, a, b), b, c)
//
// It runs over pseudo-random partitions rather than hand-picked ones, because
// an implementation that re-anchors to now passes every round span and only
// fails on the ones that land mid-period. The generator is a fixed LCG, so a
// failure is reproducible.
func TestSplitInvariant(t *testing.T) {
	rates := []Rate{
		mustNew(t, 1, 60, 0),      // one a minute, unbounded
		mustNew(t, 7, 13, 0),      // coprime, so remainders never line up
		mustNew(t, 1, 60, 500),    // capped
		mustNew(t, 250, 3600, 0),  // coarse period
		mustNew(t, 1, 1, 0),       // degenerate: every tick pays
		mustNew(t, 3, 1000, 1234), // capped and coarse
	}

	seed := uint64(0x9E3779B97F4A7C15)
	next := func(n int64) int64 {
		seed = seed*6364136223846793005 + 1442695040888963407
		return int64(seed>>33) % n
	}

	for _, r := range rates {
		for i := 0; i < 400; i++ {
			start := next(10000)
			span := next(100000)
			stock := next(600)
			end := start + span

			wantStock, wantAnchor, err := r.Advance(stock, start, end)
			uassert.NoError(t, err)

			// Cut the span into between one and six pieces and walk them.
			cuts := next(6) + 1
			gotStock, gotAnchor := stock, start
			at := start
			for c := int64(0); c < cuts; c++ {
				remaining := end - at
				if remaining <= 0 {
					break
				}
				step := next(remaining + 1)
				if c == cuts-1 {
					step = remaining
				}
				at += step
				gotStock, gotAnchor, err = r.Advance(gotStock, gotAnchor, at)
				uassert.NoError(t, err)
			}
			// Land on the end whatever the cuts did.
			gotStock, gotAnchor, err = r.Advance(gotStock, gotAnchor, end)
			uassert.NoError(t, err)

			uassert.Equal(t, wantStock, gotStock, "split stock diverged")
			uassert.Equal(t, wantAnchor, gotAnchor, "split anchor diverged")
		}
	}
}

// TestClaimingEveryTickIsNotFree is the regression for the bug this package
// exists to make unrepresentable. r/moul/x/daily/tamagotchi truncated its
// per-call decay, so acting every tick cost nothing and acting rarely cost
// everything. Here the two agree exactly.
func TestClaimingEveryTickIsNotFree(t *testing.T) {
	r := mustNew(t, 1, 60, 0)
	const span = 6000 // 100 whole periods

	oneShot, _, err := r.Advance(0, 0, span)
	uassert.NoError(t, err)

	for _, cadence := range []int64{1, 2, 7, 60, 61, 599, 3000} {
		stock, anchor := int64(0), int64(0)
		for at := cadence; at <= span; at += cadence {
			stock, anchor, err = r.Advance(stock, anchor, at)
			uassert.NoError(t, err)
		}
		stock, _, err = r.Advance(stock, anchor, span)
		uassert.NoError(t, err)
		uassert.Equal(t, oneShot, stock, "cadence changed the payout")
	}
}

// TestAtMatchesAdvance pins that the read path cannot drift from the write
// path, which was the second and quieter half of the tamagotchi bug.
func TestAtMatchesAdvance(t *testing.T) {
	r := mustNew(t, 5, 17, 900)
	for now := int64(3); now < 4000; now += 37 {
		want, _, err := r.Advance(11, 3, now)
		uassert.NoError(t, err)
		got, err := r.At(11, 3, now)
		uassert.NoError(t, err)
		uassert.Equal(t, want, got, "At diverged from Advance")
	}
}

func TestAdvanceRejects(t *testing.T) {
	r := mustNew(t, 1, 60, 0)

	_, _, err := r.Advance(-1, 0, 100)
	uassert.ErrorIs(t, err, ErrNegativeStock)

	_, _, err = r.Advance(0, 100, 99)
	uassert.ErrorIs(t, err, ErrBackwards)

	// A Rate built by literal instead of New is still checked.
	_, _, err = Rate{}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadAmount)
	_, _, err = Rate{Amount: 1}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadPeriod)
	_, _, err = Rate{Amount: 1, Period: 1, Cap: -1}.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrBadCap)
}

func TestAdvanceOverflow(t *testing.T) {
	// An uncapped rate that would pass int64 refuses rather than wrapping
	// into a negative stock, which is how a large vesting grant once
	// reported a negative balance.
	r := mustNew(t, maxInt64/2, 1, 0)
	_, _, err := r.Advance(0, 0, 100)
	uassert.ErrorIs(t, err, ErrOverflow)

	// The same rate with a cap always has an answer, so it gives one
	// instead of an error, whichever of the two guards it trips.
	capped := mustNew(t, maxInt64/2, 1, 1000)
	got, anchor, err := capped.Advance(0, 0, 100)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1000), got)
	uassert.Equal(t, int64(100), anchor, "a saturated advance still moves the anchor")

	got, _, err = capped.Advance(999, 0, 1)
	uassert.NoError(t, err)
	uassert.Equal(t, int64(1000), got, "the sum guard saturates too")

	// A negative anchor far enough below now wraps the elapsed span itself.
	slow := mustNew(t, 1, maxInt64, 0)
	_, _, err = slow.Advance(0, -10, maxInt64-5)
	uassert.ErrorIs(t, err, ErrOverflow)
}

func TestFull(t *testing.T) {
	cases := []struct {
		name                     string
		amount, period, capacity int64
		stock, anchor            int64
		want                     int64
	}{
		{"uncapped never fills", 1, 60, 0, 0, 1000, 0},
		{"already full is now", 1, 60, 10, 10, 1000, 1000},
		{"past full is now", 1, 60, 10, 99, 1000, 1000},
		{"empty takes the whole cap", 1, 60, 10, 0, 1000, 1600},
		{"partly full takes the rest", 1, 60, 10, 4, 1000, 1360},
		{"rounds up to the payout that crosses", 3, 60, 10, 0, 0, 240},
		{"exact division does not round up", 5, 60, 10, 0, 0, 120},
	}
	for _, tc := range cases {
		r := mustNew(t, tc.amount, tc.period, tc.capacity)
		got, err := r.Full(tc.stock, tc.anchor)
		uassert.NoError(t, err, tc.name)
		uassert.Equal(t, tc.want, got, tc.name)
	}
}

// TestFullAgreesWithAdvance checks the two halves of the API against each
// other: at the time Full names, the stock is at the cap, and one period
// earlier it is not.
func TestFullAgreesWithAdvance(t *testing.T) {
	for _, r := range []Rate{
		mustNew(t, 1, 60, 10),
		mustNew(t, 3, 60, 10),
		mustNew(t, 7, 13, 1000),
		mustNew(t, 250, 3600, 875),
	} {
		full, err := r.Full(0, 0)
		uassert.NoError(t, err)

		atFull, err := r.At(0, 0, full)
		uassert.NoError(t, err)
		uassert.Equal(t, r.Cap, atFull, "not full at the time Full named")

		before, err := r.At(0, 0, full-r.Period)
		uassert.NoError(t, err)
		if before >= r.Cap {
			t.Errorf("already full a period early: %d >= %d", before, r.Cap)
		}
	}
}

func TestFullRejects(t *testing.T) {
	r := mustNew(t, 1, 60, 10)
	_, err := r.Full(-1, 0)
	uassert.ErrorIs(t, err, ErrNegativeStock)

	_, err = Rate{}.Full(0, 0)
	uassert.ErrorIs(t, err, ErrBadAmount)

	far := mustNew(t, 1, maxInt64/2, 1000)
	_, err = far.Full(0, 0)
	uassert.ErrorIs(t, err, ErrOverflow)
}

// Package across reads one address across fifteen other realms that are
// already live, and renders everything they will say about it on one page.
//
// It is a composability demo with a working product hiding inside it. The
// realms it reads were written months apart, by nobody coordinating, and none
// of them knows this one exists. Not a line of them changed to make this
// possible: the only requirement any of them had to meet was NOT declaring
// `private = true`, which is what lets another realm import it at all.
//
// # Why this realm holds no state and extracts no library
//
// Every other realm here splits into a pure `p/` and a thin `r/`. This one
// cannot, and that is the point: its entire content is the wiring. Fifteen
// import lines, one call each, and a table. Extract a library and what is left
// on both sides is empty.
//
// # What it measures, besides balances
//
// The signatures below are the honest half of the demo. Eight of these realms
// hold a per-address balance and they agree on nothing:
//
//	erc20, vestoken, wrapped     BalanceOf(address) uint64
//	pairs/aaa, pairs/bbb         BalanceOf(address) int64
//	grc20faucet                  BalanceOf(symbol string, owner address) int64
//	wikicoin                     BalanceOf(address) uint
//	dice                         RollsOf(addr string) []int
//
// Three integer widths, two signednesses, one that takes the address as a
// string, one that needs a symbol first. Composition works anyway, because a
// gno import is a type-checked contract with a permanent artifact behind it and
// not a call convention anyone has to agree on in advance. It just costs one
// hand-written adapter per source, which is what the report function is.
//
// # The two sources that could not be read
//
//   - r/moul/x/amm/v0 exports SharesOf(keyA, keyB string, owner address), and
//     it routes through mustPool, which PANICS when the pool does not exist.
//     A getter that panics is not composable: fifteen sources on one page means
//     one panicking source takes the whole page down, and a wrapper cannot
//     recover, because recover() does not catch a cross-realm abort. So amm
//     contributes PoolCount() to the index and nothing to a report.
//   - r/moul/demo/vault/v0 exports MyBalance() with no address parameter. It
//     answers for whoever is calling, which from here is this realm, so the
//     value is structurally unreadable from outside.
//
// Neither is a bug in those realms. Both are what a getter looks like when
// nobody has tried to call it from another realm yet.
package across

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"

	"gno.land/r/moul/demo/wikicoin/v0"
	"gno.land/r/moul/reactions/v0"
	"gno.land/r/moul/x/amm/v0"
	"gno.land/r/moul/x/daily/dice/v0"
	"gno.land/r/moul/x/daily/erc20/v0"
	"gno.land/r/moul/x/daily/lottery/v0"
	"gno.land/r/moul/x/daily/ratelimitdemo/v0"
	"gno.land/r/moul/x/daily/staking/v0"
	"gno.land/r/moul/x/daily/streak/v0"
	"gno.land/r/moul/x/daily/vestoken/v0"
	"gno.land/r/moul/x/daily/wrapped/v0"
	"gno.land/r/moul/x/grc20faucet/v0"
	"gno.land/r/moul/x/pairs/aaa/v0"
	"gno.land/r/moul/x/pairs/aaabbb/v0"
	"gno.land/r/moul/x/pairs/bbb/v0"
)

// reactionPage is the page key handed to r/moul/reactions. Reactions are keyed
// on an arbitrary page string rather than on a realm, so a reader of this
// report is asked about the same page /u/moul shows.
const reactionPage = "gno.land/r/moul/home"

// Self is this realm's own package path, exported so a caller can build a link
// back without hardcoding the version.
const Self = "gno.land/r/moul/x/across/v0"

// A fact is one answer from one source realm about one address.
//
// zero is carried separately from value because "0" and "none" are the common
// answer and the table is worth reading only for the rows that are not that.
type fact struct {
	source string // package path, without the gno.land/ prefix
	what   string
	value  string
	zero   bool
}

// Report collects what every wired source says about who.
//
// Every call in here is a plain exported read on another realm: no cur realm,
// no cross, nothing written. A read with no realm parameter is borrowed rather
// than entered (AGENTS.md), so none of these realms even observes a caller.
func Report(who address) []fact {
	out := []fact{}

	add := func(source, what string, n int64, unit string) {
		v := strconv.FormatInt(n, 10)
		if unit != "" {
			v += " " + unit
		}
		out = append(out, fact{source: source, what: what, value: v, zero: n == 0})
	}

	// Balances. Eight sources, five signatures.
	add("r/moul/x/daily/erc20/v0", "balance", int64(erc20.BalanceOf(who)), erc20.Symbol())
	add("r/moul/x/daily/vestoken/v0", "liquid balance", int64(vestoken.BalanceOf(who)), vestoken.Symbol())
	add("r/moul/x/daily/wrapped/v0", "wrapped balance", int64(wrapped.BalanceOf(who)), "WGNOT")
	add("r/moul/demo/wikicoin/v0", "balance", int64(wikicoin.BalanceOf(who)), "WIKI")
	add("r/moul/x/pairs/aaa/v0", "balance", aaa.BalanceOf(who), "AAA")
	add("r/moul/x/pairs/bbb/v0", "balance", bbb.BalanceOf(who), "BBB")
	add("r/moul/x/grc20faucet/v0", "balance", grc20faucet.BalanceOf("RED", who), "RED")
	add("r/moul/x/grc20faucet/v0", "balance", grc20faucet.BalanceOf("BLUE", who), "BLUE")

	// A grant is three numbers, so it does not fit the add helper.
	total, claimed, claimable := vestoken.GrantOf(who)
	out = append(out, fact{
		source: "r/moul/x/daily/vestoken/v0",
		what:   "vesting grant",
		value: strconv.FormatUint(total, 10) + " total, " +
			strconv.FormatUint(claimed, 10) + " claimed, " +
			strconv.FormatUint(claimable, 10) + " claimable",
		zero: total == 0,
	})

	// Positions.
	add("r/moul/x/pairs/aaabbb/v0", "LP shares", aaabbb.SharesOf(who), "")
	add("r/moul/x/daily/staking/v0", "staked", int64(staking.StakedOf(who)), "")
	add("r/moul/x/daily/staking/v0", "unclaimed rewards", int64(staking.Earned(who)), "")

	// Activity.
	add("r/moul/x/daily/streak/v0", "current streak", int64(streak.Current(who)), "day(s)")
	add("r/moul/x/daily/streak/v0", "best streak", int64(streak.Best(who)), "day(s)")
	add("r/moul/x/daily/dice/v0", "dice rolled", int64(len(dice.RollsOf(who.String()))), "")
	add("r/moul/x/daily/ratelimitdemo/v0", "rate-limit tokens left", int64(ratelimitdemo.Tokens(who)), "")

	entered := "no"
	if lottery.HasEntered(who) {
		entered = "yes, round " + strconv.Itoa(lottery.CurrentRound())
	}
	out = append(out, fact{
		source: "r/moul/x/daily/lottery/v0",
		what:   "entered the lottery",
		value:  entered,
		zero:   !lottery.HasEntered(who),
	})

	// reactions answers with a palette key, already validated at write time, so
	// it never carries caller markdown into this table.
	react := reactions.ReactionOf(reactionPage, who)
	shown := react
	if shown == "" {
		shown = "none"
	}
	out = append(out, fact{
		source: "r/moul/reactions/v0",
		what:   "reaction on " + reactionPage,
		value:  shown,
		zero:   react == "",
	})

	return out
}

// sourceRealms is every realm this one imports for its data, in import order.
// It is the single place the count comes from: the index table has one row per
// entry and TestSourcesCoverReport checks that Report names nothing else.
//
// Fifteen entries, which is the number the prose says. TestSourceCount pins it.
var sourceRealms = []string{
	"r/moul/x/daily/erc20/v0",
	"r/moul/x/daily/vestoken/v0",
	"r/moul/x/daily/wrapped/v0",
	"r/moul/demo/wikicoin/v0",
	"r/moul/x/pairs/aaa/v0",
	"r/moul/x/pairs/bbb/v0",
	"r/moul/x/grc20faucet/v0",
	"r/moul/x/pairs/aaabbb/v0",
	"r/moul/x/amm/v0",
	"r/moul/x/daily/staking/v0",
	"r/moul/x/daily/streak/v0",
	"r/moul/x/daily/dice/v0",
	"r/moul/x/daily/lottery/v0",
	"r/moul/x/daily/ratelimitdemo/v0",
	"r/moul/reactions/v0",
}

// Sources reports how many realms this one reads.
func Sources() int { return len(sourceRealms) }

func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	addr := address(path)
	if !addr.IsValid() {
		return "# across\n\n" + ui.Empty(ui.Inline(ui.Short(path))+" is not a valid address.") +
			"\n[back to the index](/r/moul/x/across/v0)\n"
	}
	return renderAddress(addr)
}

func renderAddress(who address) string {
	var b strings.Builder
	b.WriteString("# across: " + ui.AddrFull(who) + "\n\n")
	b.WriteString("What " + strconv.Itoa(Sources()) + " independently deployed realms say about this address. ")
	b.WriteString("None of them was changed to answer.\n\n")

	facts := Report(who)

	live := ui.NewTable("source", "fact", "value")
	quiet := 0
	for _, f := range facts {
		if f.zero {
			quiet++
			continue
		}
		live.Row("[`"+f.source+"`](/"+f.source+")", f.what, f.value)
	}

	if live.Len() == 0 {
		b.WriteString(ui.Empty("Every one of the " + strconv.Itoa(len(facts)) +
			" reads came back empty. This address has never touched any of them."))
		b.WriteString("\n")
	} else {
		b.WriteString("## Answers\n\n")
		b.WriteString(live.String())
		b.WriteString("\n")
		b.WriteString(strconv.Itoa(quiet) + " of " + strconv.Itoa(len(facts)) +
			" reads came back empty and are hidden.\n\n")
	}

	b.WriteString("[back to the index](/r/moul/x/across/v0)\n")
	return b.String()
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# across\n\n")
	b.WriteString("One address, read across " + strconv.Itoa(Sources()) + " realms that are already on chain.\n\n")
	b.WriteString("Open `/r/moul/x/across/v0:<address>` to get the report. ")
	b.WriteString("Example: [/r/moul/x/across/v0:" + exampleAddr + "](/r/moul/x/across/v0:" + exampleAddr + ").\n\n")

	b.WriteString("## Why this realm exists\n\n")
	b.WriteString("A gno realm that does not declare `private = true` can be imported by any ")
	b.WriteString("other realm, forever, at a path that can never be replaced. That makes every ")
	b.WriteString("exported read on it a permanent public API. This realm is what happens when ")
	b.WriteString("somebody actually uses " + strconv.Itoa(Sources()) + " of them at once.\n\n")
	b.WriteString("Nothing here was negotiated. No registry, no interface, no shared base ")
	b.WriteString("package, no version handshake, and no change to any source realm.\n\n")

	b.WriteString("## The sources, and what each one is showing right now\n\n")
	t := ui.NewTable("realm", "global reading")
	t.Row("[`r/moul/x/daily/erc20/v0`](/r/moul/x/daily/erc20/v0)",
		erc20.Symbol()+" supply "+strconv.FormatUint(erc20.TotalSupply(), 10))
	t.Row("[`r/moul/x/daily/vestoken/v0`](/r/moul/x/daily/vestoken/v0)",
		vestoken.Symbol()+" supply "+strconv.FormatUint(vestoken.TotalSupply(), 10))
	t.Row("[`r/moul/x/daily/wrapped/v0`](/r/moul/x/daily/wrapped/v0)",
		"wrapped supply "+strconv.FormatUint(wrapped.TotalSupply(), 10))
	t.Row("[`r/moul/demo/wikicoin/v0`](/r/moul/demo/wikicoin/v0)", "per-address balances only")
	t.Row("[`r/moul/x/pairs/aaa/v0`](/r/moul/x/pairs/aaa/v0)",
		"AAA supply "+strconv.FormatInt(aaa.TotalSupply(), 10))
	t.Row("[`r/moul/x/pairs/bbb/v0`](/r/moul/x/pairs/bbb/v0)",
		"BBB supply "+strconv.FormatInt(bbb.TotalSupply(), 10))
	t.Row("[`r/moul/x/grc20faucet/v0`](/r/moul/x/grc20faucet/v0)",
		"RED supply "+strconv.FormatInt(grc20faucet.TotalSupply("RED"), 10)+
			", BLUE supply "+strconv.FormatInt(grc20faucet.TotalSupply("BLUE"), 10))
	t.Row("[`r/moul/x/pairs/aaabbb/v0`](/r/moul/x/pairs/aaabbb/v0)",
		"LP shares "+strconv.FormatInt(aaabbb.TotalShares(), 10))
	t.Row("[`r/moul/x/amm/v0`](/r/moul/x/amm/v0)",
		strconv.Itoa(amm.PoolCount())+" pool(s), index only (see below)")
	t.Row("[`r/moul/x/daily/staking/v0`](/r/moul/x/daily/staking/v0)", "per-address stake and rewards")
	t.Row("[`r/moul/x/daily/streak/v0`](/r/moul/x/daily/streak/v0)",
		"day "+strconv.FormatInt(streak.Day(), 10))
	t.Row("[`r/moul/x/daily/dice/v0`](/r/moul/x/daily/dice/v0)",
		strconv.Itoa(dice.Total())+" roll(s) all time")
	t.Row("[`r/moul/x/daily/lottery/v0`](/r/moul/x/daily/lottery/v0)",
		"round "+strconv.Itoa(lottery.CurrentRound())+", "+
			strconv.Itoa(lottery.NumEntrants())+" entrant(s)")
	t.Row("[`r/moul/x/daily/ratelimitdemo/v0`](/r/moul/x/daily/ratelimitdemo/v0)", "per-address bucket")
	t.Row("[`r/moul/reactions/v0`](/r/moul/reactions/v0)",
		strconv.Itoa(reactions.Pages())+" page(s) reacted to")
	b.WriteString(t.String())
	b.WriteString("\n")

	b.WriteString("## What it cost\n\n")
	b.WriteString("Eight of these hold a per-address balance, and they share no signature: ")
	b.WriteString("`uint64` three times, `int64` twice, `uint` once, one that wants a symbol ")
	b.WriteString("before the address, one that wants the address as a `string`. Every source ")
	b.WriteString("therefore needs its own adapter line. That is the whole cost, and it is paid ")
	b.WriteString("once by the reader rather than up front by fifteen authors.\n\n")

	b.WriteString("## The two that could not be read\n\n")
	b.WriteString("- `r/moul/x/amm/v0` routes `SharesOf` through a helper that panics on an ")
	b.WriteString("unknown pool. One panicking source takes down a page built from " +
		strconv.Itoa(Sources()) + ", and ")
	b.WriteString("`recover()` does not catch a cross-realm abort, so only its `PoolCount()` is ")
	b.WriteString("safe to call from here.\n")
	b.WriteString("- `r/moul/demo/vault/v0` exports `MyBalance()` with no address parameter. It ")
	b.WriteString("answers for its caller, which from here is this realm.\n\n")
	b.WriteString("Neither is a bug. Both are what a getter looks like before anyone has tried ")
	b.WriteString("to call it from another realm.\n")

	return b.String()
}

// exampleAddr is moul's address, used only to give the index a link that
// resolves to a real report instead of an empty one.
const exampleAddr = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"

package across

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"

	"gno.land/r/moul/x/daily/erc20/v0"
	"gno.land/r/moul/x/daily/streak/v0"
	"gno.land/r/moul/x/pairs/aaa/v0"
	"gno.land/r/moul/x/pairs/bbb/v0"
)

// seeded is the address the mutation tests build state for. Everything after
// TestReportReadsCrossRealmState sees whatever they left in the imported
// realms, which is the whole point of the demo but also makes test order load
// bearing: nothing below may assume a clean source realm for this address.
var seeded = testutils.TestAddress("across-seeded")

// fresh is never written to by anything here, so every source answers it with
// its zero value. ExampleRender pins that page.
var fresh = testutils.TestAddress("across-fresh")

func TestSourceCount(t *testing.T) {
	// The package doc and the rendered prose both say fifteen. If this fails,
	// one of them is now a lie.
	uassert.Equal(t, 15, Sources())
}

// Report must never name a realm that sourceRealms does not list, or the index
// table silently stops covering what the report reads.
func TestSourcesCoverReport(t *testing.T) {
	known := map[string]bool{}
	for _, s := range sourceRealms {
		known[s] = true
	}
	for _, f := range Report(fresh) {
		uassert.True(t, known[f.source], "report names an unlisted source: "+f.source)
	}
}

// Every source answers, and no source panics. The count is asserted rather
// than the values, so this stays true as the sources gain state.
func TestReportAnswersFromEverySource(t *testing.T) {
	facts := Report(fresh)
	uassert.Equal(t, 18, len(facts))

	seen := map[string]bool{}
	for _, f := range facts {
		seen[f.source] = true
	}
	// amm is the one listed source that contributes to the index only.
	uassert.Equal(t, 14, len(seen))
	uassert.False(t, seen["r/moul/x/amm/v0"], "amm must not be read per address")
}

// The load-bearing test: write to four realms that know nothing about this one,
// then read all four back through Report. Break any of the four reads and this
// goes red.
func TestReportReadsCrossRealmState(cur realm, t *testing.T) {
	// SetRealm governs only the crossing calls made from this frame, so the
	// switch has to stay inline with the calls it is meant to cover.
	testing.SetRealm(testing.NewUserRealm(seeded))
	erc20.Mint(cross(cur), seeded, 4_200)
	aaa.Faucet(cross(cur))
	bbb.Faucet(cross(cur))
	days := streak.CheckIn(cross(cur))
	uassert.Equal(t, 1, days, "first check-in is day 1")

	got := map[string]string{}
	for _, f := range Report(seeded) {
		if f.zero {
			continue
		}
		got[f.source+" "+f.what] = f.value
	}

	uassert.Equal(t, "4200 "+erc20.Symbol(), got["r/moul/x/daily/erc20/v0 balance"])
	uassert.Equal(t, "1 day(s)", got["r/moul/x/daily/streak/v0 current streak"])
	uassert.Equal(t, "1 day(s)", got["r/moul/x/daily/streak/v0 best streak"])
	uassert.True(t, got["r/moul/x/pairs/aaa/v0 balance"] != "", "aaa faucet must show up")
	uassert.True(t, got["r/moul/x/pairs/bbb/v0 balance"] != "", "bbb faucet must show up")
}

// The rendered page for the seeded address must carry the same four facts, and
// must hide the reads that came back empty rather than printing a wall of zeros.
func TestRenderAddressShowsOnlyLiveFacts(t *testing.T) {
	out := Render(seeded.String())

	uassert.True(t, strings.Contains(out, "4200 "+erc20.Symbol()), "erc20 balance on the page")
	uassert.True(t, strings.Contains(out, "current streak"), "streak on the page")
	uassert.True(t, strings.Contains(out, "r/moul/x/pairs/aaa/v0"), "aaa on the page")
	uassert.True(t, strings.Contains(out, "reads came back empty and are hidden"), "quiet rows hidden")
